export class Config {
    constructor() { }
}

Config.GAME_NAME = "BTDemoGame"; // no special chars or space

// ratio 4/3
Config.STAGEWIDTH = 1024;
Config.STAGEHEIGHT = 768;

Config.STAGEWIDTH2 = 512;
Config.STAGEHEIGHT2 = 384;

Config.DEFAULT_STAGECOLOR = 0x21496D;

Config.PLAYTIME = 90;

Config.VERSION = "0.4.3";
Config.DEBUG = false;

// flashvars : objet optionnel defini par la page html (voir index.html)
Config.ASSETS_PATH = (typeof flashvars !== "undefined" && flashvars.ASSETS_PATH) || "assets/";

Config.PAUSE_ON_BLUR = false;

// registered fonts
Config.DEFAULT_FONT = 'ShagExpert-Lounge';
Config.VECTOR_FUTURE_FONT = 'kenvector_future';

// Color Theme, Android style :)
Config.style = {};
Config.style.PRIMARY_LIGHT = 0x74b9ff; // The color of the status bar
Config.style.PRIMARY = 0x0984e3; // The brand color
Config.style.PRIMARY_DARK = 0x0a3d62; // The color of the status bar
Config.style.ACCENT = 0xe84393; // Used for components in “activated” state

Config.style.SECONDARY = 0x3F51B5; // same RGB as primary but 85%
Config.style.TERTIARY = 0x3F51B5; // same RGB as primary but 50%

Config.style.CONTROL_NORMAL = 0xfab1a0; // the default state color of components
Config.style.CONTROL_ACTIVATED = 0xe17055; // the default state color of components

Config.style.COLOR_BACKGROUND = 0x2d3436; // the background color of the activity
Config.style.COLOR_FOREGROUND = 0xdfe6e9; // inverse of Background and used for certain components


// Default keyboard layout
// valeurs de KeyboardEvent.code (position physique de la touche, independante du layout)
Config.UP = "KeyW"; // z en AZERTY
Config.DOWN = "KeyS"; // s
Config.LEFT = "KeyA"; // q en AZERTY
Config.RIGHT = "KeyD"; // d

Config.ACTION1 = "Space";
Config.ACTION2 = "KeyE"; // e
Config.ACTION3 = "KeyQ"; // a en AZERTY

// Palette Gamebuino
Config.color = {};
Config.color.BLACK = 0x000000;
Config.color.DARKBLUE = 0x004385;
Config.color.PURPLE = 0x960040;
Config.color.GREEN = 0x008B50;
Config.color.BROWN = 0xCF8E44;
Config.color.DARKGRAY = 0x544D43;
Config.color.GRAY = 0xA89987;
Config.color.WHITE = 0xFFFFFF;
Config.color.RED = 0xDB1D23;
Config.color.ORANGE = 0xFFA811;
Config.color.YELLOW = 0xF5E700;
Config.color.LIGHTGREEN = 0x85CF44;
Config.color.LIGHTBLUE = 0x7DBBFF;
Config.color.BLUE = 0x4485CF;
Config.color.MAGENTA = 0xCF4485;
