import { BaseButton } from './BaseButton.js';
import { Gamepad } from './Gamepad.js';
import { Key } from './Key.js';
import { Config } from './Config.js';

export class GameInput {
    constructor(player_id) {
        this._gamepad = new Gamepad(player_id);

        this.UP = 0;
        this.DOWN = 1;
        this.LEFT = 2;
        this.RIGHT = 3;

        this.ACTION1 = 4;
        this.ACTION2 = 5;
        this.ACTION3 = 6;

        this._id = player_id;
        this._time = 0; // horloge de jeu (secondes), avancee par update(), sert a l'input buffer
        this._target = null;
        this._type = GameInput.KEYBOARD;
        this._keyboard = null;
        this._demoLayout = null;
        this._userLayout = null;

        this._createKeys([
            GameInput.UP, GameInput.DOWN, GameInput.LEFT, GameInput.RIGHT,
            GameInput.ACTION1, GameInput.ACTION2, GameInput.ACTION3
        ]);
    }

    // pUp... : valeurs de KeyboardEvent.code, ex "KeyW", "Space"
    changeKeyLayout(pUp, pDown, pLeft, pRight, p1, p2, p3) {
        // disposition voulue par la demo : gardee pour pouvoir y revenir (setUserLayout(null))
        this._demoLayout = [pUp, pDown, pLeft, pRight, p1, p2, p3];
        // une disposition choisie par le joueur (panneau d'options) l'emporte sur celle de la demo
        this._applyLayout(this._userLayout || this._demoLayout);
    }

    _applyLayout(pCodes) {
        [GameInput.UP, GameInput.DOWN, GameInput.LEFT, GameInput.RIGHT,
        GameInput.ACTION1, GameInput.ACTION2, GameInput.ACTION3] = pCodes;
        this._createKeys(pCodes);
    }

    /** codes des 7 touches actuelles, dans l'ordre de GameInput.NAMES */
    get layout() { return this._keyboard.map((k) => k.code); }

    /**
     * Disposition choisie par le joueur : tableau de 7 codes (appliquee tout de suite, et conservee quand
     * la demo appelle changeKeyLayout), ou null pour revenir a celle de la demo.
     */
    setUserLayout(pCodes) {
        this._userLayout = pCodes ? pCodes.slice() : null;
        const codes = this._userLayout || this._demoLayout;
        if (codes) this._applyLayout(codes);
    }

    _createKeys(pCodes) {
        if (this._keyboard) this._keyboard.forEach((key) => key.destroy());

        this._keyboard = pCodes.map((code, i) => {
            const key = new Key(code, () => this._time);
            const name = GameInput.NAMES[i];
            // -- on press (front montant : une seule fois par appui)
            key.press = () => {
                if (!this._target) return;
                this._target[name + "OnPress"]();
            };
            // -- on release
            key.release = () => {
                if (!this._target) return;
                this._target[name + "OnRelease"]();
            };
            return key;
        });
    }

    set target(target) { this._target = target; }
    get target() { return this._target; }

    set type(type) { this._type = type; }
    get type() { return this._type; }

    get keyboard() {
        return this._keyboard;
    }

    /**
     * Branche un bouton Pixi (BaseButton) sur une action : utile pour les controles tactiles.
     * @param pButton un BaseButton
     * @param pName   "up" | "down" | "left" | "right" | "action1" | "action2" | "action3"
     */
    bindButton(pButton, pName) {
        pButton.on(BaseButton.POINTER_DOWN, () => this[pName].setSource("touch", true));
        pButton.on(BaseButton.POINTER_UP, () => this[pName].setSource("touch", false));
        pButton.on(BaseButton.POINTER_UP_OUTSIDE, () => this[pName].setSource("touch", false));
    }

    // la manette alimente les memes Key que le clavier (plus de faux KeyboardEvent)
    _pollGamepad() {
        const active = this._gamepad.isActive;
        GameInput.PAD_MAP.forEach((buttons, i) => {
            const pressed = active && buttons.some((b) => this._gamepad.isPressed(b));
            this._keyboard[i].setSource("pad", pressed);
        });
    }

    /** temps de jeu en secondes (cumul des dt passes a update) */
    get time() { return this._time; }

    /**
     * A appeler une fois par frame, avec le dt REEL en secondes (pas celui du pas fixe).
     * Fait avancer l'horloge de l'input buffer, lit la manette puis appelle les xxxIsDown().
     */
    update(dt) {
        this._time += dt;
        if (!this._target) return;

        this._pollGamepad();

        // un xxxIsDown() peut changer d'ecran (le ScreenManager retire alors la cible) : on relit la cible a chaque touche
        GameInput.NAMES.forEach((name, i) => {
            const target = this._target;
            if (target && this._keyboard[i].isDown) {
                target[name + "IsDown"]();
            }
        });
    }

    get up() { return this._keyboard[this.UP]; }

    get down() { return this._keyboard[this.DOWN] }

    get left() { return this._keyboard[this.LEFT] }

    get right() { return this._keyboard[this.RIGHT] }

    get action1() { return this._keyboard[this.ACTION1] }

    get action2() { return this._keyboard[this.ACTION2] }

    get action3() { return this._keyboard[this.ACTION3] }
}

GameInput.KEYBOARD = "gamecontroller::keyboard";
GameInput.GAMEPAD = "gamecontroller::gamepad";

GameInput.NAMES = ["up", "down", "left", "right", "action1", "action2", "action3"];
// boutons de la manette (standard mapping) pour chaque action, dans l'ordre de NAMES
GameInput.PAD_MAP = [[12], [13], [14], [15], [2, 3], [1, 5], [0, 4]];

GameInput.UP = Config.UP;
GameInput.DOWN = Config.DOWN;
GameInput.LEFT = Config.LEFT;
GameInput.RIGHT = Config.RIGHT;

GameInput.ACTION1 = Config.ACTION1;
GameInput.ACTION2 = Config.ACTION2;
GameInput.ACTION3 = Config.ACTION3;