import { EventBroker } from '../core/EventBroker.js';
import { MessageEvent } from '../core/MessageEvent.js';
import { Container, Graphics, Text } from '../core/fff.js';
import { Config } from './Config.js';

export class Pause {
    constructor() {
        let container = new Container();

        let text = new Text("- PAUSE -", Config.base_style_24);
        text.x = (Config.STAGEWIDTH - text.width) >> 1;
        text.y = 1 / 3 * Config.STAGEHEIGHT;

        let bg = new Graphics();
        bg.beginFill(0x0, 1 / 3);
        bg.drawRect(0, 0, Config.STAGEWIDTH, Config.STAGEHEIGHT);
        bg.endFill();

        container.addChild(bg);
        container.addChild(text);

        container.eventMode = 'static';
        container.cursor = 'pointer';

        container.on('pointertap', function () {
            let me = new MessageEvent(MessageEvent.SCREEN_RESUMED, this);
            EventBroker.broadcast(me);
        });

        return container;
    }
}