import { gsap } from 'gsap';
import { EventBroker } from '../core/EventBroker.js';
import { MessageEvent } from '../core/MessageEvent.js';
import { Graphics, Text } from '../core/fff.js';
import { PIXI } from '../lib/pixi.js';
import { ScreenManager } from './ScreenManager.js';
import { BT } from './BT.js';
import { Config } from './Config.js';
import { Datas } from './Datas.js';
import { GameInput } from './GameInput.js';
import { MenuNavigator } from './MenuNavigator.js';

export class BaseScreen {
	constructor() {
		// l'ecran courant est connu du ScreenManager des la construction
		ScreenManager._register(this);
		this._destroyed = false;

		this._nextScreen = null;
		this._stage = BT.stage;
		this._pause = false;
		this._msgBox = null;
		this._subscriptions = [];

		this._screenName = this.constructor.name + "Screen";
		this._dc = BT.dc;

		this.gameInput1 = BT.getGameInput(1);

		// call start method, puis l'effet d'arrivee
		this.start();
		this.transitionIn();
	}

	start() {
		this.visible = false;

		// event broker
		let me = new MessageEvent(MessageEvent.SCREEN_START, this);
		EventBroker.broadcast(me);

		this.subscribe(MessageEvent.MSG_BOX, (pMe) => { this.onClickMessageBox(pMe) });

		// game engine version
		let message = new Text("ver. " + BT.version, Config.base_style_10);
		message.position.set(Config.STAGEWIDTH - message.width - 13, Config.STAGEHEIGHT - message.height - 13);
		BT.stage.addChild(message);
	}

	onEnterFrame(fr) {
		// -- to override
	};

	/**
	 * Abonnement a l'EventBroker lie a la vie de l'ecran :
	 * il est automatiquement supprime dans destroy().
	 */
	subscribe(pMessageEventType, pCallBack) {
		this._subscriptions.push(EventBroker.subscribe(pMessageEventType, pCallBack));
	}

	/**
	 * L'ecran a termine : on passe a l'ecran suivant (this.nextScreen).
	 * Sans effet si l'ecran est deja detruit (ex: un setTimeout qui arrive trop tard).
	 */
	end() {
		if (this._destroyed) return;
		ScreenManager.goTo(this._nextScreen);
	}

	// --------------------------------------------------
	// -- TRANSITIONS
	//
	// Chaque ecran a deux accroches, appelees par le moteur ou par l'ecran lui-meme :
	//   transitionIn()  : appelee automatiquement une fois l'ecran demarre (start() termine)
	//   transitionOut() : a appeler quand l'ecran a fini ; elle doit se terminer par this.end()
	// Par defaut elles font un effet generique (voir ci-dessous). Un ecran qui veut sa propre animation
	// SURCHARGE la methode (ex. : le joueur qui s'estompe devant la porte), commence par
	// `if (!this._beginTransition()) return;` puis appelle this.end() quand il a fini ; il peut aussi
	// rappeler super.transitionOut(options) pour ajouter l'effet generique a sa propre animation.
	//
	//   this.nextScreen = FightScreen; this.transitionOut({ effect: 'flash', color: 0xAA0000 });
	//   this.transitionTo(FightScreen, { effect: 'flash', color: 0xAA0000 });   // meme chose en une ligne
	//
	// Options (identiques pour transitionIn et transitionOut) :
	//   effect   : 'none' (defaut), 'flash' (eclair qui s'estompe) ou 'fade' (fondu vers/depuis la couleur)
	//   color    : couleur de l'effet (defaut 0xFFFFFF)
	//   duration : duree de l'effet en secondes (defaut 1/3 pour flash, 0.6 pour fade)
	//   freeze   : (transitionOut) true = l'ecran n'est plus mis a jour (onEnterFrame suspendu) pendant la sortie ;
	//              les tweens GSAP continuent. Defaut false (l'ecran continue d'animer).
	//   loading  : (transitionOut) true ou { message, color, fade, minTime, minFrames } : sortie par un ecran de
	//              chargement (voile + barre) pendant lequel l'ecran suivant se construit et "chauffe", voir
	//              ScreenManager.loadScreen. Un ecran peut definir isReady() pour faire attendre le chargement.
	//   delay    : (transitionOut) attente avant de quitter l'ecran, en secondes (defaut 0 = tout de suite)
	//   onStart  : fonction appelee au debut

	/**
	 * Debut de transition : renvoie false si une transition est deja en cours (un second appel est ignore).
	 * pLockInput : coupe les entrees (gameInput1.target = null) pendant la transition.
	 */
	_beginTransition(pLockInput = true, pFreeze = false) {
		if (this._transitioning || this._destroyed) return false;
		this._transitioning = true;
		if (pLockInput) this.gameInput1.target = null;
		if (pFreeze) this._frozen = true;
		return true;
	}

	/** vrai si onEnterFrame est suspendu (option freeze d'une transition) ; contrairement a pause, rien n'est affiche */
	/** navigation de menu au clavier / manette (voir MenuNavigator) */
	get menu() {
		if (!this._menu) this._menu = new MenuNavigator(this);
		return this._menu;
	}

	get frozen() { return !!this._frozen; }
	set frozen(value) { this._frozen = !!value; }

	/** vrai pendant une transition de sortie */
	get transitioning() { return !!this._transitioning; }

	/** effet visuel generique ; pReverse = true : de la couleur vers la scene (arrivee) */
	_transitionEffect(pOptions, pReverse = false) {
		const { effect = 'none', color = 0xFFFFFF, onStart = null } = pOptions;
		if (onStart) onStart();
		if (effect === 'flash') {
			this.flash(color, 1.0, pOptions.duration ?? 1 / 3);
		} else if (effect === 'fade') {
			const veil = new Graphics();
			veil.beginFill(color, 1.0);
			veil.drawRect(0, 0, Config.STAGEWIDTH, Config.STAGEHEIGHT);
			veil.endFill();
			veil.eventMode = 'none';
			veil.alpha = pReverse ? 1 : 0;
			this.stage.addChild(veil);
			gsap.to(veil, {
				duration: pOptions.duration ?? 0.6, alpha: pReverse ? 0 : 1,
				onComplete: () => { if (pReverse && veil.parent) veil.parent.removeChild(veil); }
			});
		}
	}

	/** Arrivee sur l'ecran. Par defaut : aucun effet (surcharger, ou passer des options depuis start()). */
	transitionIn(pOptions = {}) {
		this._transitionEffect(pOptions, true);
	}

	/**
	 * Sortie de l'ecran vers this.nextScreen : effet, entrees coupees, puis end() apres `delay` secondes.
	 * Le delai passe par gsap : il est annule proprement si l'ecran est detruit entre-temps.
	 * @returns true si la transition a demarre, false si une transition etait deja en cours
	 */
	transitionOut(pOptions = {}) {
		if (!this._beginTransition(true, !!pOptions.freeze)) return false;
		this._transitionEffect(pOptions);
		if (pOptions.loading) {
			// sortie par l'ecran de chargement (fondu, construction de l'ecran suivant derriere le voile, fondu)
			const loading = pOptions.loading === true ? {} : pOptions.loading;
			gsap.delayedCall(pOptions.delay ?? 0, () => ScreenManager.loadScreen(this._nextScreen, loading));
			return true;
		}
		gsap.delayedCall(pOptions.delay ?? 0, () => this.end());
		return true;
	}

	/** Raccourci : choisit l'ecran suivant puis lance transitionOut. */
	transitionTo(pNextScreen, pOptions = {}) {
		this._nextScreen = pNextScreen;
		return this.transitionOut(pOptions);
	}

	/**
	 * Libere tout ce que l'ecran possede. Appele par le ScreenManager quand on quitte l'ecran.
	 * Pour nettoyer des objets propres a un ecran : surcharger, nettoyer, puis appeler super.destroy().
	 */
	destroy() {
		if (this._destroyed) return;
		this._destroyed = true;

		// plus d'entrees vers une entite qui n'existe plus
		this.gameInput1.target = null;

		this._subscriptions.forEach((unsubscribe) => unsubscribe());
		this._subscriptions = [];
		gsap.globalTimeline.clear(); // tous les tweens et delayedCall en cours

		// un shake interrompu laisserait la scene decalee
		BT.stage.x = BT.stage.y = 0;
		this._disposeStage();

		let me = new MessageEvent(MessageEvent.SCREEN_DESTROYED, this);
		EventBroker.broadcast(me);
	}

	/**
	 * Detruit les objets Pixi de la scene (geometries, canvas de texte...), sauf ceux partages
	 * entre ecrans (Datas.atlas) qui sont seulement retires de la scene. Les textures ne sont pas detruites.
	 */
	_disposeStage() {
		const shared = new Set(Object.values(Datas.atlas).filter((value) => value instanceof PIXI.Container));

		const dispose = (displayObject) => {
			if (displayObject._persistent) return; // le voile de chargement survit au changement d'ecran
			if (shared.has(displayObject)) {
				if (displayObject.parent) displayObject.parent.removeChild(displayObject);
				return;
			}
			if (displayObject.children && displayObject.children.length) displayObject.children.slice().forEach(dispose);
			displayObject.destroy();
		};

		BT.stage.children.slice().forEach(dispose);
	}

	clearContainer(pContainer) {
		while (pContainer.children.length > 0) {
			pContainer.removeChildAt(0);
		}
	}

	trace() {
		BT.dc.trace(arguments);
	}

	// --------------------------------------------------
	// FX

	/**
	 * Secoue la scene (tween GSAP : suit le ticker et s'arrete avec l'ecran)
	 */
	shake(pPower = 15, pQuakes = 10) {
		const stage = this.stage;
		const quake = () => {
			stage.x = (Math.random() * pPower) - pPower;
			stage.y = (Math.random() * pPower) - pPower;
		};

		gsap.killTweensOf(stage);
		quake();
		gsap.to(stage, {
			duration: 0.04,
			repeat: pQuakes - 1,
			onRepeat: quake,
			onComplete: () => { stage.x = stage.y = 0; }
		});
	}

	flash(pColor, pAlpha = 1.0, pDuration = 1 / 3) {
		let screen = this;
		pColor = (typeof pColor) !== 'undefined' ? pColor : 0x808080;

		let flash = new Graphics();
		flash.beginFill(pColor, pAlpha);
		flash.drawRect(0, 0, Config.STAGEWIDTH, Config.STAGEHEIGHT);
		flash.endFill();

		flash.eventMode = 'none';
		screen.stage.addChild(flash);

		gsap.to(flash, { duration: pDuration, alpha: 0, onComplete: function () { screen.stage.removeChild(flash) } });
	}

	showMessageBox(pFlag, pTitle, pText, pPosition = null) {
		if (this._msgBox) {
			this.hideMessageBox();
			this._msgBox = null;
		}
		let dialog = this._msgBox = BT.createMessageBox(pFlag, pTitle, pText);
		if (pPosition == null) {
			dialog.position.set(Config.STAGEWIDTH2, Config.STAGEHEIGHT2);
		} else {
			dialog.position = pPosition;
		}
		this.stage.addChild(dialog);
		// navigation clavier / manette entre les boutons de la boite
		this.menu.show(dialog.buttonLayoutContainer.children);
	}

	hideMessageBox() {
		if (this._menu) this._menu.hide();
		if (this._msgBox) {
			if (this._msgBox.parent) {
				this._msgBox.parent.removeChild(this._msgBox);
			}
		}
	}

	// override me
	onClickMessageBox(pMe) {
		this.hideMessageBox();
	}

	// Action du joueur (touches/boutons ACTION1/2/3), appelee par le Player de l'ecran.
	// pAction : GameInput.ACTION1, ACTION2 ou ACTION3. Override me.
	// Par defaut ACTION1 appelle playerHitSpace() (ancien nom, conserve pour compatibilite).
	playerAction(pAction) {
		if (pAction === GameInput.ACTION1) this.playerHitSpace();
	}

	// ancien hook "espace" : prefere surcharger playerAction()
	playerHitSpace() { }

	// --------------------------------------------------
	// -- properties

	//get view() { return this._view	}
	get stage() { return this._stage }
	get dc() { return this._dc }
	get screenName() { return this._screenName }

	get nextScreen() { return this._nextScreen }
	set nextScreen(value) { this._nextScreen = value }

	// pause the game
	get pause() {
		return this._pause;
	}

	// la pause est un simple flag : la boucle principale (Main.js) n'appelle plus onEnterFrame
	set pause(value) {
		value = !!value;
		if (value === this._pause) return;

		this._pause = value;
		if (value) {
			this.stage.addChild(Datas.atlas[Datas.PAUSE]);
		} else {
			this.stage.removeChild(Datas.atlas[Datas.PAUSE]);
		}
	}

	unpause() {
		this.pause = false;
	}

	// lose focus
	deactivate() {
		if (Config.PAUSE_ON_BLUR == true)
			this.pause = true;
	};

	mouseLock() {
		BT.domContainer.style.pointerEvents = "none";
	};

	//https://developer.mozilla.org/fr/docs/Web/CSS/pointer-events
	// les enfants peuvent override override pointer-events, du coup ca fonctionne(rait) comme avec mouseChildren
	mouseUnlock() {
		BT.domContainer.style.pointerEvents = "auto";
	};

	get visible() { return BT.domContainer.style.display !== 'none' }
	set visible(value) { BT.domContainer.style.display = (value === false) ? 'none' : 'block' }
}