import { TextStyle } from './core/fff.js';
import { EventBroker } from './core/EventBroker.js';
import { MessageEvent } from './core/MessageEvent.js';
import { BT } from './engine/BT.js';
import { Console } from './engine/Console.js';
import { FpsMeter } from './engine/FpsMeter.js';
import { ErrorOverlay } from './engine/ErrorOverlay.js';
import { Save } from './core/Save.js';
import { OptionsPanel } from './engine/OptionsPanel.js';
import { isValidLayout } from './engine/KeyLayout.js';
import { Config } from './engine/Config.js';
import { Datas } from './engine/Datas.js';
import { Pause } from './engine/Pause.js';
import { ScreenManager } from './engine/ScreenManager.js';
import { SoundManager } from './engine/SoundManager.js';
import { Preload } from './engine/Preload.js';
import { demoIdFromUrl, loadDemo } from './demos/index.js';

(async function () {
    // erreurs : message lisible au lieu d'un ecran fige (installe en premier, avant le chargement de la demo)
    ErrorOverlay.install({
        onFatal: () => { if (BT.ticker) BT.ticker.stop(); },
        context: () => ({
            ecran: ScreenManager.current ? ScreenManager.current.constructor.name : '(aucun)',
            demo: new URLSearchParams(window.location.search).get('demo') || '(defaut)'
        })
    });

    class BlankTemplate {

        constructor(pDomTarget) {
            this.config = new Config();

            this.domTarget = pDomTarget;

            // App Style
            Config.base_style_10 = new TextStyle({
                fontFamily: Config.VECTOR_FUTURE_FONT,
                fill: Config.style.ACCENT,
                fontSize: 10
            });

            Config.base_style_12 = new TextStyle({
                fontFamily: Config.DEFAULT_FONT,
                fill: Config.style.PRIMARY,
                fontSize: 12
            });

            Config.base_style_24 = new TextStyle({
                fontFamily: Config.VECTOR_FUTURE_FONT,
                fill: Config.style.PRIMARY,
                fontSize: 24
            });

            // visual debug console
            BT.dc = this.dc = new Console(document.getElementById("debugPanel"));

            // events handling -- app level
            EventBroker.subscribe(MessageEvent.SCREEN_START, function (me) {
                BT.dc.addMessage("start", me.datas.screenName);
            });
            EventBroker.subscribe(MessageEvent.SCREEN_RESUMED, function (me) {
                ScreenManager.current.unpause();
            });

        }

        // le renderer de Pixi 8 s'initialise de facon asynchrone
        async start() {
            const pDomTarget = this.domTarget;

            // create and initialize the renderer
            await BT.init(pDomTarget);

            // sauvegarde locale (options, meilleur score...) : voir core/Save.js ; a augmenter si le format change
            Save.init({
                name: 'blanktemplate',
                version: 1,
                defaults: { volume: 1, muted: false, best1500: 0 }
            });
            SoundManager.volume = Save.get('volume');
            SoundManager.muted = Save.get('muted');

            // touches choisies par le joueur pour cette demo (le panneau d'options les ecrit), avant que la demo ne pose les siennes
            const demoId = demoIdFromUrl();
            const gameInput = BT.getGameInput(1);
            const keys = Save.get('keys:' + demoId);
            if (isValidLayout(keys)) gameInput.setUserLayout(keys);
            Datas.init();
            SoundManager.preload(SoundManager.CLICK);
            Datas.atlas[Datas.PAUSE] = new Pause();

            // Ticker
            BT.ticker.stop();
            // compteur de performance : ?fps dans l'URL, ou touche F3
            const fps = FpsMeter.install();
            if (Save.get('fps')) fps.toggle(true);
            // panneau d'options : touche F1 ou engrenage
            OptionsPanel.install({ gameInput, fps, demoId });
            BT.ticker.add(function (delta) {
                fps.update(BT.ticker.elapsedMS);
                ScreenManager.update(BT.ticker.elapsedMS / 1000);
            });

            // creating preload screen
            ScreenManager.goTo(Preload);

            window.addEventListener(MessageEvent.ON_BLUR, function () {
                if (ScreenManager.current) ScreenManager.current.deactivate();
            });
        }
    }

    // demo choisie par le parametre d'URL (?demo=hex), voir demos/index.js
    const demo = await loadDemo(demoIdFromUrl());
    // une demo peut avoir ses propres reglages (taille de l'ecran, police...) : a appliquer avant tout le reste
    if (demo.config) {
        Object.assign(Config, demo.config);
        if (demo.config.STAGEWIDTH) {
            document.documentElement.style.setProperty('--stage-ratio', demo.config.STAGEWIDTH / demo.config.STAGEHEIGHT);
        }
    }
    Preload.demo = demo;

    const app = new BlankTemplate(document.getElementById("gameContainer"));
    await app.start();
    return app;
})();