/**
 * [trace description]
 * @return [description]
 */
export function trace() {
    return console.log.apply(console, arguments);
}

export function log() {
    return console.log.apply(console, arguments);
}

/**
 * [describe description]
 * @param  pObject  [description]
 * @return          [description]
 */
export function describe(pObject) {
    let result = JSON.stringify(pObject)
    trace(result);
    return result;
}

/**
 * [getURL description]
 * @param  url      [description]
 * @param  sOptions [description]
 * @param  sTitle   [description]
 * @return          [description]
 */
export function getURL(url, sOptions, sTitle) {
    sOptions = (typeof sOptions === "undefined") ? "" : sOptions;
    sTitle = (typeof sTitle === "undefined") ? "" : sTitle;

    if (sOptions !== "") {
        if (sOptions === "_blank") {
            window.open(url);
            return false;
        } else {
            window.open(url, sTitle, sOptions);
            return false;
        }
    } else {
        if (window.location.href === url) {
            window.location.reload();
        } else {
            window.location.href = url;
        }
    }
}

