// ADAPTATEURS PIXI
//
// Classes qui gardent l'API simple de ce template au-dessus de PixiJS 8
// (Text(texte, style), Sprite(texture), Graphics avec beginFill/drawRect/lineTo...)

/**
 * Convertit un style de texte au format "Pixi 4" (options a plat) vers le format Pixi 8 :
 * dropShadow* -> objet dropShadow, stroke + strokeThickness -> { color, width },
 * fill en tableau -> degrade vertical.
 */
export function convertTextStyle(pStyle = {}) {
    if (pStyle instanceof PIXI.TextStyle) return pStyle;

    const o = Object.assign({}, pStyle);

    if (o.dropShadow === true) {
        o.dropShadow = {
            color: o.dropShadowColor !== undefined ? o.dropShadowColor : '#000000',
            alpha: o.dropShadowAlpha !== undefined ? o.dropShadowAlpha : 1,
            blur: o.dropShadowBlur !== undefined ? o.dropShadowBlur : 0,
            angle: o.dropShadowAngle !== undefined ? o.dropShadowAngle : Math.PI / 6,
            distance: o.dropShadowDistance !== undefined ? o.dropShadowDistance : 5
        };
    } else {
        delete o.dropShadow;
    }
    ['dropShadowColor', 'dropShadowAlpha', 'dropShadowBlur', 'dropShadowAngle', 'dropShadowDistance'].forEach((k) => delete o[k]);

    if (o.stroke !== undefined && typeof o.stroke !== 'object') {
        o.stroke = { color: o.stroke, width: o.strokeThickness !== undefined ? o.strokeThickness : 1 };
    }
    delete o.strokeThickness;

    if (Array.isArray(o.fill)) {
        const last = Math.max(o.fill.length - 1, 1);
        o.fill = new PIXI.FillGradient({
            type: 'linear',
            start: { x: 0, y: 0 },
            end: { x: 0, y: 1 },
            colorStops: o.fill.map((color, i) => ({ offset: i / last, color })),
            textureSpace: 'local'
        });
    }

    return o;
}

/**
 * Branche sur un objet interactif ses methodes nommees comme des evenements
 * (pointerdown(e), pointerup(e), pointerupoutside(e), pointermove(e), globalpointermove(e)...).
 * globalpointermove est livre meme quand le curseur n'est pas sur l'objet : a utiliser pour un drag & drop.
 * Pixi 4 les appelait tout seul ; Pixi 8 demande de les enregistrer.
 */
export function bindPointerHandlers(pDisplayObject) {
    ['pointerdown', 'pointerup', 'pointerupoutside', 'pointermove', 'globalpointermove', 'pointerover', 'pointerout', 'pointertap'].forEach((name) => {
        if (typeof pDisplayObject[name] === 'function') {
            pDisplayObject.on(name, (pEvent) => pDisplayObject[name](pEvent));
        }
    });
}

export class TextStyle extends PIXI.TextStyle {
    constructor(pOptions) {
        super(convertTextStyle(pOptions));
    }
}

