// SPRITE

/**
 * let sprite = new Sprite(texture);
 * (une chaine est cherchee dans les textures deja chargees, voir Assets)
 */
export class Sprite extends PIXI.Sprite {
    constructor(texture) {
        if (texture !== undefined && !(texture instanceof PIXI.Texture)) {
            texture = PIXI.Texture.from(texture);
        }
        super(texture);
    }
}

///////////////////////////////////////////////
// GRAPHIC

/**
 * Graphics avec l'API "a l'ancienne" (Pixi 4) :
 *
 *   g.lineStyle(2, 0xFF0000);
 *   g.beginFill(0x0000FF);
 *   g.drawRect(0, 0, 100, 50);
 *   g.endFill();
 *   g.moveTo(0, 0); g.lineTo(50, 50);
 *
 * Pixi 8 fonctionne autrement (on dessine un chemin puis on appelle fill() / stroke()) :
 * cette classe garde le style courant et applique fill / stroke apres chaque forme.
 * Une ligne (lineTo) est tracee des qu'elle est ajoutee ; le remplissage d'un chemin
 * moveTo/lineTo est applique par endFill() (ou au debut de la forme suivante).
 */
export class Graphics extends PIXI.Graphics {
    constructor() {
        super();
        this._lineStyle = null;
        this._fillStyle = null;
        this._fillPoints = null;
        this._cursorX = 0;
        this._cursorY = 0;
    }

    lineStyle(pWidth = 0, pColor = 0, pAlpha = 1) {
        this._flushFill();
        this._lineStyle = pWidth > 0 ? { width: pWidth, color: pColor, alpha: pAlpha } : null;
        return this;
    }

    beginFill(pColor = 0, pAlpha = 1) {
        this._flushFill();
        this._fillStyle = { color: pColor, alpha: pAlpha };
        return this;
    }

    endFill() {
        this._flushFill();
        this._fillStyle = null;
        return this;
    }

    clear() {
        super.clear();
        this._lineStyle = null;
        this._fillStyle = null;
        this._fillPoints = null;
        this._cursorX = this._cursorY = 0;
        return this;
    }

    moveTo(pX, pY) {
        this._flushFill();
        this._cursorX = pX;
        this._cursorY = pY;
        if (this._fillStyle) this._fillPoints = [pX, pY];
        return this;
    }

    lineTo(pX, pY) {
        if (this._lineStyle) {
            super.beginPath();
            super.moveTo(this._cursorX, this._cursorY);
            super.lineTo(pX, pY);
            this.stroke(this._lineStyle);
        }
        if (this._fillStyle) {
            if (!this._fillPoints) this._fillPoints = [this._cursorX, this._cursorY];
            this._fillPoints.push(pX, pY);
        }
        this._cursorX = pX;
        this._cursorY = pY;
        return this;
    }

    /**
     * Trace d'un coup un lot de segments independants avec un seul style : une seule commande de
     * dessin au lieu d'une par lineTo (beaucoup plus leger pour des centaines de lignes).
     * @param pSegments tableau plat [x1, y1, x2, y2, x1, y1, ...]
     * @param pLength   nombre de valeurs a lire dans pSegments (4 par segment)
     */
    strokeSegments(pSegments, pLength, pWidth, pColor, pAlpha = 1) {
        if (pLength <= 0) return this;
        this._flushFill();
        super.beginPath();
        for (let i = 0; i < pLength; i += 4) {
            super.moveTo(pSegments[i], pSegments[i + 1]);
            super.lineTo(pSegments[i + 2], pSegments[i + 3]);
        }
        this.stroke({ width: pWidth, color: pColor, alpha: pAlpha });
        return this;
    }

    drawRect(pX, pY, pWidth, pHeight) {
        return this._paintShape(() => super.rect(pX, pY, pWidth, pHeight));
    }

    drawRoundedRect(pX, pY, pWidth, pHeight, pRadius) {
        return this._paintShape(() => super.roundRect(pX, pY, pWidth, pHeight, pRadius));
    }

    drawCircle(pX, pY, pRadius) {
        return this._paintShape(() => super.circle(pX, pY, pRadius));
    }

    drawEllipse(pX, pY, pHalfWidth, pHalfHeight) {
        return this._paintShape(() => super.ellipse(pX, pY, pHalfWidth, pHalfHeight));
    }

    // pPoints : [x0, y0, x1, y1, ...]
    drawPolygon(pPoints) {
        return this._paintShape(() => super.poly(pPoints, true));
    }

    _paintShape(pDraw) {
        this._flushFill();
        super.beginPath();
        pDraw();
        if (this._fillStyle) this.fill(this._fillStyle);
        if (this._lineStyle) this.stroke(this._lineStyle);
        return this;
    }

    // remplit le chemin moveTo/lineTo en cours (au moins 3 points)
    _flushFill() {
        const points = this._fillPoints;
        this._fillPoints = null;
        if (points && this._fillStyle && points.length >= 6) {
            super.beginPath();
            super.poly(points, false);
            this.fill(this._fillStyle);
        }
    }
}

