// TILING SPRITE

export class TilingSprite extends PIXI.TilingSprite {
    constructor(texture, width, height) {
        if (!(texture instanceof PIXI.Texture)) {
            texture = PIXI.Texture.from(texture);
        }
        super({ texture, width, height });
    }
}

