// Texture

/**
 * @param texture   une texture existante (on partage sa source)
 * @param rectangle la zone a decouper dans cette texture
 */
export class Texture extends PIXI.Texture {
    constructor(texture, rectangle) {
        super({ source: texture.source, frame: rectangle });
    }
}

