/**
 * Texte avec l'ancienne signature : new Text("texte", { fontSize: 16, fill: 0xFFFFFF })
 * Le style peut etre un objet d'options (format Pixi 4 ou 8) ou un TextStyle.
 */
export class Text extends PIXI.Text {
    constructor(text = "", styleObject) {
        super({ text, style: convertTextStyle(styleObject) });
    }
}

///////////////////////////////////////////////
// Point & Rectangle
//

export class Point extends PIXI.Point {
    constructor(x, y) {
        super(x, y);
    }
}

export class Rectangle extends PIXI.Rectangle {
    constructor(x, y, w, h) {
        super(x, y, w, h);
    }

    get bottomRight() { return new Point(this.right, this.bottom) }

    get topLeft() { return new Point(this.left, this.top) }

    get size() { return new Point(this.width, this.height) }

    /**
     * @return Whether the two rectangles intersects
     */
    intersects(rect) {
        if (rect.x < (this.x + this.width) && this.x < rect.x + rect.width && rect.y < this.y + this.height) {
            return this.y < rect.y + rect.height;
        }

        return false;
    }

    /**
     * @return Returns the area of intersection as a Rectangle object. If the rectangles do not intersect, this method returns an empty Rectangle object with its properties set to 0.
     */
    intersection(rect) {
        if (this.intersects(rect)) {
            const left = this.x > rect.x ? this.x : rect.x;
            const right = this.right < rect.right ? this.right : rect.right;
            const top = this.y > rect.y ? this.y : rect.y;
            const bottom = this.bottom < rect.bottom ? this.bottom : rect.bottom;

            return new Rectangle(left, top, right - left, bottom - top);
        }

        return new Rectangle();
    }

    /**
     * @return Adds two rectangles together to create a new Rectangle object, by filling in the horizontal and vertical space between the two rectangles.
     */
    union(rect) {
        const top = this.y < rect.y ? this.y : rect.y;
        const left = this.x < rect.x ? this.x : rect.x;
        const right = this.right > rect.right ? this.right : rect.right;
        const bottom = this.bottom > rect.bottom ? this.bottom : rect.bottom;

        return new Rectangle(left, top, right - left, bottom - top);
    }
}

