import '../lib/pixi.js';
import { EventBroker } from '../core/EventBroker.js';
import { MessageEvent } from '../core/MessageEvent.js';
import { Container, Sprite, Text, TextStyle } from '../core/fff.js';
import { BaseButton } from './BaseButton.js';
import { ButtonScale3 } from './ButtonScale3.js';
import { Config } from './Config.js';
import { Datas } from './Datas.js';

export class MsgBox extends Container {

    /////////////////////////////////////////
    // TODO

    // - ICON
    // - 1 poil plus grand (taille dynamique ?)
    // - croix pour fermer
    // - drag & drop
    // - un drop shadow, glow
    // - une shadow box
    // - un fx d'apparition

    /**
     * @param {*} pFlag Indique le type de boîte de message et les combinaisons de boutons possibles.Voir remarques.
     * @param {*} pTitle Le titre de la boîte de message.
     * @param {*} pText Le texte de la boîte de message
     * @param {*} pTimeOut timeout[optionnel] Temporisation en secondes.Après la temporisation, la boite de message sera automatiquement fermée.La valeur par défaut est 0, ce qui équivaut à aucune temporisation.
     */
    constructor(pFlag, pTitle, pText, pTimeOut = 0) {
        super();

        this.container = new Container();
        this.container.position.set(-160, -100);
        this.addChild(this.container);

        // background
        this.container.addChild(Datas.atlas[Datas.MESSAGE_BOX]);

        // title & text
        let fontStyleTitle = new TextStyle({
            fontFamily: Config.VECTOR_FUTURE_FONT,
            fill: Config.style.PRIMARY_DARK,
            wordWrap: true,
            wordWrapWidth: 320 - 10,
            fontSize: 14
        });

        let fontStyleText = new TextStyle({
            fontFamily: Config.VECTOR_FUTURE_FONT,
            fill: Config.style.PRIMARY_DARK,
            align: "left",
            wordWrap: true,
            wordWrapWidth: (320*2) - 10,
            fontSize: 14
        });

        let title = new Text(pTitle, fontStyleTitle);
        title.position.set(15, 7);
        this.container.addChild(title);

        let myText = new Text(pText, fontStyleText);
        myText.position.set(15, 37);
        this.container.addChild(myText);

        let buttonLayout;
        let iconTexture;

        if (pFlag >= MsgBox.MB_ICON_INFORMATION) {
            // MB_ICON_INFORMATION
            buttonLayout = pFlag - MsgBox.MB_ICON_INFORMATION;
            iconTexture = Datas.atlas[Datas.MESSAGE_BOX_INFORMATION];
        } else if (pFlag >= MsgBox.MB_ICON_WARNING) {
            // MB_ICON_ERROR
            buttonLayout = pFlag - MsgBox.MB_ICON_WARNING;
            iconTexture = Datas.atlas[Datas.MESSAGE_BOX_EXCLAMATION];
        } else if (pFlag >= MsgBox.MB_ICON_QUESTION) {
            // MB_ICON_QUESTION
            buttonLayout = pFlag - MsgBox.MB_ICON_QUESTION;
            iconTexture = Datas.atlas[Datas.MESSAGE_BOX_QUESTION];
        } else if (pFlag >= MsgBox.MB_ICON_ERROR) {
            // MB_ICON_WARNING
            buttonLayout = pFlag - MsgBox.MB_ICON_ERROR;
            iconTexture = Datas.atlas[Datas.MESSAGE_BOX_WARNING];
        } else {
            buttonLayout = pFlag - MsgBox.MB_NO_ICON;
            iconTexture = null;
        }

        // icon s
        this.addIcon(iconTexture);

        // buttons
        this.buttonLayoutContainer = new Container();
        switch (buttonLayout) {
            case MsgBox.MB_OK_CANCEL:
                this.addButton(new ButtonScale3("OK", 0, 0, 80), MsgBox.OK);
                this.addButton(new ButtonScale3("CANCEL", 0, 0, 80), MsgBox.CANCEL);
                break;

            case MsgBox.MB_ABORT_RETRY_IGNORE:
                this.addButton(new ButtonScale3("ABORT", 0, 0, 80), MsgBox.ABORT);
                this.addButton(new ButtonScale3("RETRY", 0, 0, 80), MsgBox.RETRY);
                this.addButton(new ButtonScale3("IGNORE", 0, 0, 80), MsgBox.IGNORE);
                break;

            case MsgBox.MB_YES_NO_CANCEL:
                this.addButton(new ButtonScale3("YES", 0, 0, 80), MsgBox.YES);
                this.addButton(new ButtonScale3("NO", 0, 0, 80), MsgBox.NO);
                this.addButton(new ButtonScale3("CANCEL", 0, 0, 80), MsgBox.CANCEL);
                break;

            case MsgBox.MB_YES_NO:
                this.addButton(new ButtonScale3("YES", 0, 0, 80), MsgBox.YES);
                this.addButton(new ButtonScale3("NO", 0, 0, 80), MsgBox.NO);
                break;

            case MsgBox.MB_RETRY_CANCEL:
                this.addButton(new ButtonScale3("RETRY", 0, 0, 80), MsgBox.RETRY);
                this.addButton(new ButtonScale3("CANCEL", 0, 0, 80), MsgBox.CANCEL);
                break;

            case MsgBox.MB_CANCEL_RETRY_CONTINUE:
                this.addButton(new ButtonScale3("CANCEL", 0, 0, 80), MsgBox.CANCEL);
                this.addButton(new ButtonScale3("RETRY", 0, 0, 80), MsgBox.RETRY);
                this.addButton(new ButtonScale3("CONTINUE", 0, 0, 80), MsgBox.CONTINUE);
                break;

            default:
                this.addButton(new ButtonScale3("OK", 0, 0, 80), MsgBox.OK);
                break;
        }
        this.buttonLayoutContainer.position.set(155, 175);
        this.container.addChild(this.buttonLayoutContainer);
    }

    addIcon(pTexture) {
        if (pTexture) {
            let icon = new Sprite(pTexture);
            icon.position.set(285, 2);
            icon.scale.set(.25, .25);
            this.container.addChild(icon);
        }
    }

    addButton(pButtonScale3, pValue) {
        // event broker
        pButtonScale3.on(BaseButton.POINTER_UP, (pEvent) => {
            let me = new MessageEvent(MessageEvent.MSG_BOX, pValue);
            EventBroker.broadcast(me);
        });

        // layout
        let prevBtn;
        if (this.buttonLayoutContainer.children.length == 0) {
            pButtonScale3.position.set(0, 0);
        }
        if (this.buttonLayoutContainer.children.length == 1) {
            prevBtn = this.buttonLayoutContainer.getChildAt(0);
            prevBtn.position.x -= (80 / 2 + 20 / 2);

            pButtonScale3.position.x = prevBtn.position.x + prevBtn.width + 20;
        }

        if (this.buttonLayoutContainer.children.length == 2) {
            const prevprevBtn = this.buttonLayoutContainer.getChildAt(0);
            prevprevBtn.position.x -= (80 / 2 + 20 / 2);

            prevBtn = this.buttonLayoutContainer.getChildAt(1);
            prevBtn.position.x -= (80 / 2 + 20 / 2);

            pButtonScale3.position.x = prevBtn.position.x + prevBtn.width + 20;
        }
        this.buttonLayoutContainer.addChild(pButtonScale3);
    }
}

// result
MsgBox.OK = 1;
MsgBox.CANCEL = 2;
MsgBox.ABORT = 3;
MsgBox.RETRY = 4;
MsgBox.IGNORE = 5;
MsgBox.YES = 6;
MsgBox.NO = 7;
MsgBox.CONTINUE = 8;

// boutons
MsgBox.MB_OK = 0;
MsgBox.MB_OK_CANCEL = 1;
MsgBox.MB_ABORT_RETRY_IGNORE = 2;
MsgBox.MB_YES_NO_CANCEL = 3;
MsgBox.MB_YES_NO = 4;
MsgBox.MB_RETRY_CANCEL = 5;
MsgBox.MB_CANCEL_RETRY_CONTINUE = 6;

// icon
MsgBox.MB_NO_ICON = 0;
MsgBox.MB_ICON_ERROR = 16;
MsgBox.MB_ICON_QUESTION = 32;
MsgBox.MB_ICON_WARNING = 48;
MsgBox.MB_ICON_INFORMATION = 64;

// message event for event broker
