/**
 * Affichage lisible des erreurs : au lieu d'un ecran fige (une exception dans le ticker ou un asset introuvable
 * arrete tout sans rien dire), on arrete le jeu et on affiche le message, la pile, le contexte (demo, ecran,
 * graine du hasard...) et deux boutons : Copier (pour le coller dans un rapport de bug) et Recharger.
 *
 *   ErrorOverlay.install({
 *       context: () => ({ demo: ..., ecran: ..., graine: ... }),   // optionnel : infos ajoutees au rapport
 *       onFatal: () => BT.ticker.stop()                            // optionnel : arreter le jeu
 *   });
 *
 * Capte window 'error' et 'unhandledrejection'. Seule la PREMIERE erreur est detaillee (les suivantes sont
 * souvent des consequences) ; les autres sont comptees. Test rapide depuis la console : setTimeout(() => { throw new Error("test") })
 */

/** transforme n'importe quelle valeur levee (Error, string, objet...) en { name, message, stack } */
export function describeError(pValue) {
    if (pValue instanceof Error) {
        return { name: pValue.name, message: pValue.message, stack: pValue.stack || "" };
    }
    if (typeof pValue === "string") return { name: "Error", message: pValue, stack: "" };
    let message;
    try { message = JSON.stringify(pValue); } catch { message = String(pValue); }
    return { name: "Error", message: message === undefined ? String(pValue) : message, stack: "" };
}

/** texte du rapport (ce que le bouton Copier met dans le presse-papiers) */
export function buildReport(pError, pContext = {}, pCount = 1) {
    const lines = [pError.name + " : " + pError.message];
    if (pError.stack) lines.push("", pError.stack);
    lines.push("");
    for (const [k, v] of Object.entries(pContext)) lines.push(k + " : " + v);
    if (pCount > 1) lines.push("(+ " + (pCount - 1) + " autre(s) erreur(s) apres celle-ci)");
    return lines.join("\n");
}

export class ErrorOverlay {
    static install(pOptions = {}) {
        if (ErrorOverlay._installed) return;
        ErrorOverlay._installed = true;
        ErrorOverlay._options = pOptions;
        window.addEventListener("error", (e) => {
            // les erreurs de chargement de ressources (img, script) n'ont pas de e.error : on ne les traite pas ici
            if (e.error || e.message) ErrorOverlay.show(e.error || e.message);
        });
        window.addEventListener("unhandledrejection", (e) => ErrorOverlay.show(e.reason));
    }

    static show(pValue) {
        ErrorOverlay._count = (ErrorOverlay._count || 0) + 1;
        if (ErrorOverlay._count > 1) {
            if (ErrorOverlay._counter) ErrorOverlay._counter.textContent = "+ " + (ErrorOverlay._count - 1) + " autre(s) erreur(s) apres celle-ci";
            return;
        }
        const opts = ErrorOverlay._options || {};
        if (opts.onFatal) { try { opts.onFatal(); } catch { /* deja en erreur */ } }

        const error = describeError(pValue);
        let context = {};
        if (opts.context) { try { context = opts.context(); } catch { context = { contexte: "indisponible" }; } }
        context.url = window.location.href;
        context.navigateur = navigator.userAgent;
        const report = buildReport(error, context);
        console.error(report);

        // en plein ecran, seul l'element plein ecran est visible : on sort pour afficher le message
        if (document.fullscreenElement && document.exitFullscreen) document.exitFullscreen();

        const root = document.createElement("div");
        root.style.cssText = "position:fixed;inset:0;z-index:1000;overflow:auto;box-sizing:border-box;padding:24px;" +
            "background:rgba(40,0,0,.95);color:#fff;font:14px monospace";
        const title = document.createElement("div");
        title.style.cssText = "font-size:20px;color:#f66;margin-bottom:12px";
        title.textContent = "Une erreur est survenue : le jeu est arrete";
        const pre = document.createElement("pre");
        pre.style.cssText = "white-space:pre-wrap;word-break:break-word;margin:0 0 16px";
        pre.textContent = report;
        const counter = document.createElement("div");
        counter.style.cssText = "color:#fa0;margin-bottom:12px";
        ErrorOverlay._counter = counter;

        const button = (label, fn) => {
            const b = document.createElement("button");
            b.textContent = label;
            b.style.cssText = "margin-right:8px;padding:6px 14px;font:14px monospace;cursor:pointer";
            b.onclick = fn;
            return b;
        };
        const copy = button("Copier le rapport", () => {
            if (navigator.clipboard) navigator.clipboard.writeText(report).then(() => { copy.textContent = "Copie !"; });
        });
        root.append(title, pre, counter, copy, button("Recharger", () => window.location.reload()));
        document.body.appendChild(root);
    }
}
