import { SoundManager } from './SoundManager.js';
import { Container, Sprite, bindPointerHandlers } from '../core/fff.js';

export class BaseButton extends Container {
    constructor(pTexture1, pTexture2, pX, pY) {
        super();

        this.oriX = pX;
        this.oriY = pY;

        this.x = pX;
        this.y = pY;

        this.eventMode = 'static';
        this.cursor = 'pointer';
        bindPointerHandlers(this);
        this.interactiveChildren = false;

        this.texture1 = pTexture1;
        this.texture2 = pTexture2;

        let sprite = this.sprite = new Sprite(pTexture1);
        sprite.anchor.x = sprite.anchor.y = .5;
        this.addChild(sprite);
    }

    pointerdown(pEvent) {
        if (this.texture2) {
            this.sprite.texture = this.texture2;
        }
        console.log(pEvent.currentTarget.y);
        pEvent.currentTarget.y = this.oriY + 2;
        SoundManager.play(SoundManager.CLICK);
    };

    pointerup(pEvent) {
        if (this.texture2) {
            this.sprite.texture = this.texture1;
        }
        pEvent.currentTarget.y = this.oriY;
    };

    pointerupoutside(pEvent) {
        if (this.texture2) {
            this.sprite.texture = this.texture1;
        }
        pEvent.currentTarget.y = this.oriY;
    };
}

BaseButton.CLICK = "click";
BaseButton.POINTER_DOWN = "pointerdown";
BaseButton.POINTER_UP = "pointerup";
BaseButton.POINTER_UP_OUTSIDE = "pointerupoutside";
BaseButton.POINTER_OVER = "pointerover";
BaseButton.POINTER_LEAVE = "pointerleave";