import { BT } from './BT.js';
import { LoadingOverlay } from './LoadingOverlay.js';

/**
 * Gere l'ecran courant et la navigation entre ecrans.
 *
 * Cycle de vie d'un ecran (voir BaseScreen) :
 *   new Ecran()  ->  start()  ->  onEnterFrame(dt) a chaque frame  ->  end() / destroy()
 *
 * Navigation :  ScreenManager.goTo(Game)  detruit l'ecran courant puis cree le nouveau.
 * Depuis un ecran, this.end() fait la meme chose vers this.nextScreen.
 */
export class ScreenManager {
    constructor() { }

    static get current() { return this._current }

    static goTo(pScreenClass) {
        this._cancelLoading(); // un changement d'ecran direct annule un chargement en cours
        this._switchTo(pScreenClass);
    }

    static _switchTo(pScreenClass) {
        if (!pScreenClass) {
            throw new Error("ScreenManager.goTo : classe d'ecran manquante (nextScreen non defini ?)");
        }

        const previous = this._current;
        this._current = null;
        if (previous) previous.destroy();

        // le constructeur de BaseScreen s'enregistre lui-meme (_register) avant start()
        new pScreenClass();
    }

    // appele par le constructeur de BaseScreen
    static _register(pScreen) {
        this._current = pScreen;
    }

    // appele a chaque frame par la boucle principale (Main.js)
    static update(pDt) {
        const screen = this._current;
        if (screen && !screen.pause && !screen.frozen) {
            screen.onEnterFrame(pDt);
            if (screen._menu) screen._menu.update(pDt);
        }
        if (this._load) this._updateLoading(pDt);
    }

    // --------------------------------------------------
    // -- TRANSITION AVEC ECRAN DE CHARGEMENT
    //
    // ScreenManager.loadScreen(Suivant, options) (ou, depuis un ecran, transitionTo(Suivant, { loading: options })) :
    //   1. fondu de l'ecran courant vers le voile (message + barre en bas), entrees coupees ;
    //   2. l'ecran suivant est construit DERRIERE le voile opaque, entrees toujours coupees, et tourne
    //      quelques images pour "chauffer" (premier rendu, textures envoyees au GPU...) : la saccade du premier
    //      affichage se passe sous le voile. La barre avance ; elle attend aussi screen.isReady() si l'ecran
    //      le definit (chargement asynchrone) ;
    //   3. fondu de sortie du voile, puis les entrees sont rendues a l'ecran suivant.
    // Le voile est pilote ici, par le temps reel (update), pas par gsap : gsap est vide a chaque changement d'ecran.
    //
    // Options : message ("Chargement..."), color (0x000000), fade (duree des fondus, 0.4 s),
    //           minTime (duree minimale de chargement, 0.6 s), minFrames (images de chauffe minimales, 20)

    static loadScreen(pScreenClass, pOptions = {}) {
        if (!pScreenClass) throw new Error("ScreenManager.loadScreen : classe d'ecran manquante");
        if (this._load) return false;
        const o = {
            message: "Chargement...", color: 0x000000, fade: 0.4, minTime: 0.6, minFrames: 20, ...pOptions
        };
        const view = new LoadingOverlay(o.message, o.color);
        view.alpha = 0;
        BT.stage.addChild(view);
        this._loadingView = view;
        this._load = { o, next: pScreenClass, phase: 'in', t: 0, frames: 0, shown: 0, target: null, screen: null };
        // l'ecran qui part ne reagit plus aux commandes
        if (this._current) this._current.gameInput1.target = null;
        return true;
    }

    /** vrai pendant un chargement (fondus compris) */
    static get loading() { return !!this._load; }

    static _updateLoading(pDt) {
        const L = this._load, o = L.o, view = this._loadingView;
        if (L.phase === 'in') {
            L.t += pDt;
            view.alpha = Math.min(1, L.t / o.fade);
            if (L.t >= o.fade + 1 / 30) L.phase = 'swap'; // une image de plus : le voile opaque est rendu avant la construction
        } else if (L.phase === 'swap') {
            this._switchTo(L.next);
            const screen = L.screen = this._current;
            // l'ecran se construit, mais ne recoit pas les commandes avant la fin du chargement
            L.target = screen.gameInput1.target;
            screen.gameInput1.target = null;
            BT.stage.addChild(view);
            L.phase = 'load';
            L.t = 0;
        } else if (L.phase === 'load') {
            L.t += pDt;
            L.frames++;
            BT.stage.addChild(view); // l'ecran peut avoir ajoute des objets au-dessus
            const ready = !L.screen.isReady || L.screen.isReady();
            const target = Math.min(ready ? 1 : 0.95, Math.max(L.frames / o.minFrames, L.t / o.minTime));
            L.shown += (target - L.shown) * Math.min(1, pDt * 12);
            view.progress = L.shown;
            if (ready && target >= 1 && L.shown > 0.98) {
                view.progress = 1;
                L.phase = 'out';
                L.t = 0;
            }
        } else if (L.phase === 'out') {
            L.t += pDt;
            view.alpha = Math.max(0, 1 - L.t / o.fade);
            if (L.t >= o.fade) this._endLoading(true);
        }
    }

    static _endLoading(pRestoreInput) {
        const L = this._load;
        if (!L) return;
        // les commandes reviennent a l'ecran suivant
        if (pRestoreInput && L.screen && L.screen === this._current && !L.screen.gameInput1.target) {
            L.screen.gameInput1.target = L.target;
        }
        this._cancelLoading();
    }

    static _cancelLoading() {
        if (this._loadingView) {
            if (this._loadingView.parent) this._loadingView.parent.removeChild(this._loadingView);
            this._loadingView.destroy({ children: true });
            this._loadingView = null;
        }
        this._load = null;
    }
}

ScreenManager._current = null;
ScreenManager._load = null;
ScreenManager._loadingView = null;