/**
 * Sauvegarde locale (localStorage) : options, progression, scores. Versionnee, avec migration.
 *
 *   Save.init({
 *       name: 'blanktemplate',                  // cle dans le localStorage
 *       version: 2,
 *       defaults: { options: { volume: 1, muted: false }, best: 0 },
 *       migrations: {                           // migrations[n] : passe un ancien format n-1 -> n
 *           2: (data) => ({ ...data, best: data.score || 0 })
 *       }
 *   });
 *   Save.get('best');          // valeur, ou celle de defaults
 *   Save.set('best', 1200);    // ecrit tout de suite
 *   Save.reset();              // revient aux defaults
 *
 * Robustesse : localStorage indisponible (navigation privee, quota) -> la sauvegarde reste en memoire pour
 * la session ; contenu illisible (JSON casse) -> defaults, et l'ancien texte est garde sous "<name>.corrupt".
 * Une sauvegarde plus recente que le jeu (version > version) est lue telle quelle, sans migration.
 * Le stockage est injectable (Save.init({ storage })) : c'est ce qui permet de tester sans navigateur.
 */
export class Save {
    static init(pOptions) {
        const o = pOptions || {};
        this._name = o.name || 'save';
        this._version = o.version || 1;
        this._defaults = o.defaults || {};
        this._migrations = o.migrations || {};
        this._storage = o.storage !== undefined ? o.storage : Save._browserStorage();
        this._data = this._load();
        return this;
    }

    static get(pKey, pFallback) {
        const v = this._data[pKey];
        return v !== undefined ? v : pFallback;
    }

    static set(pKey, pValue) {
        this._data[pKey] = pValue;
        this._write();
    }

    static get data() { return this._data; }

    static reset() {
        this._data = this._clone(this._defaults);
        this._write();
    }

    static _browserStorage() {
        try {
            const s = window.localStorage;
            s.setItem('__test__', '1');
            s.removeItem('__test__');
            return s;
        } catch {
            return null;
        }
    }

    static _clone(pValue) { return JSON.parse(JSON.stringify(pValue)); }

    static _load() {
        const defaults = this._clone(this._defaults);
        if (!this._storage) return defaults;
        let raw;
        try { raw = this._storage.getItem(this._name); } catch { return defaults; }
        if (raw === null || raw === undefined) return defaults;

        let env;
        try {
            env = JSON.parse(raw);
            if (!env || typeof env !== 'object' || typeof env.data !== 'object' || env.data === null) throw new Error('format');
        } catch {
            try { this._storage.setItem(this._name + '.corrupt', raw); } catch { /* quota */ }
            return defaults;
        }

        let data = env.data;
        let v = Number.isInteger(env.v) ? env.v : 0;
        while (v < this._version) {
            v++;
            if (this._migrations[v]) data = this._migrations[v](data);
        }
        // les cles ajoutees depuis la sauvegarde recoivent leur valeur par defaut
        return Object.assign(defaults, data);
    }

    static _write() {
        if (!this._storage) return false;
        try {
            this._storage.setItem(this._name, JSON.stringify({ v: this._version, data: this._data }));
            return true;
        } catch {
            return false; // quota plein : on garde la version en memoire
        }
    }
}

Save._data = {};
Save._storage = null;
