export class EventBroker {
    constructor() { }

    /**
     * Abonne un callback a un type d'evenement (plusieurs abonnes possibles par type).
     * @returns une fonction de desabonnement
     */
    static subscribe(pMessageEventType, pCallBack) {
        if (!this.events[pMessageEventType]) {
            this.events[pMessageEventType] = [];
        }
        this.events[pMessageEventType].push(pCallBack);

        return () => this.unsubscribe(pMessageEventType, pCallBack);
    }

    static unsubscribe(pMessageEventType, pCallBack) {
        const listeners = this.events[pMessageEventType];
        if (!listeners) return;

        const index = listeners.indexOf(pCallBack);
        if (index !== -1) listeners.splice(index, 1);
        if (listeners.length === 0) delete this.events[pMessageEventType];
    }

    static broadcast(pMessageEvent) {
        const listeners = this.events[pMessageEvent.messageEventType];
        if (!listeners) return;

        // copie : un abonne peut se desabonner/s'abonner pendant le broadcast
        listeners.slice().forEach((callback) => callback(pMessageEvent));
    }

    static clearAll() {
        this.events = {};
    }
}

EventBroker.events = {};