import { Container, Graphics, Text } from '../core/fff.js';
import { Config } from './Config.js';

export class PreloadBar extends Container {
    constructor() {
        super();

        let gfx = new Graphics();
        gfx.beginFill(0xFFFFFF);
        gfx.drawRect(0, 0, Config.STAGEWIDTH, 60);
        gfx.endFill();
        this.addChild(gfx);

        let text = new Text("Chargement en cours...", { fontFamily: Config.DEFAULT_FONT, fontSize: 25, fontWeight: "bold", fill: Config.style.PRIMARY_DARK, align: 'center', dropShadowAngle: Math.PI / 2 });
        text.anchor.set(.5, 0)
        text.position.set(Config.STAGEWIDTH2, 15);
        this.addChild(text);

        this.position.set(0, -60 + Config.STAGEHEIGHT * 1 / 3);
    }
}