/**
 * Fonctions pures pour le remappage des touches (utilisees par OptionsPanel).
 * Une disposition = tableau de 7 codes KeyboardEvent.code, dans l'ordre de GameInput.NAMES :
 * [up, down, left, right, action1, action2, action3].
 */

// touches reservees au moteur : jamais assignables a une action
export const RESERVED_KEYS = ['Escape', 'F1', 'F2', 'F3', 'F5', 'F11', 'F12'];

export function isReserved(pCode) {
    return RESERVED_KEYS.includes(pCode);
}

/**
 * Assigne pCode a l'action d'index pIndex. Si une autre action utilisait deja cette touche, les deux actions
 * echangent leurs touches (jamais deux actions sur la meme touche).
 * @returns une NOUVELLE disposition (l'originale n'est pas modifiee)
 */
export function assignKey(pLayout, pIndex, pCode) {
    const out = pLayout.slice();
    const other = out.indexOf(pCode);
    if (other !== -1 && other !== pIndex) out[other] = out[pIndex];
    out[pIndex] = pCode;
    return out;
}

/** libelle lisible d'un code : 'KeyW' -> 'W', 'ArrowLeft' -> '←', 'Space' -> 'Espace', 'Digit1' -> '1' */
export function keyLabel(pCode) {
    if (/^Key[A-Z]$/.test(pCode)) return pCode.slice(3);
    if (/^Digit\d$/.test(pCode)) return pCode.slice(5);
    if (/^Numpad\d$/.test(pCode)) return 'Pav.' + pCode.slice(6);
    const names = {
        ArrowLeft: '←', ArrowRight: '→', ArrowUp: '↑', ArrowDown: '↓',
        Space: 'Espace', Enter: 'Entree', ShiftLeft: 'Maj gauche', ShiftRight: 'Maj droite',
        ControlLeft: 'Ctrl gauche', ControlRight: 'Ctrl droite', AltLeft: 'Alt gauche', AltRight: 'Alt droite',
        Tab: 'Tab', Backspace: 'Retour'
    };
    return names[pCode] || pCode;
}

/** valide une disposition lue dans la sauvegarde (7 codes texte, tous differents) */
export function isValidLayout(pLayout) {
    return Array.isArray(pLayout) && pLayout.length === 7 &&
        pLayout.every((c) => typeof c === 'string' && c.length > 0 && !isReserved(c)) &&
        new Set(pLayout).size === 7;
}
