/**
 * Navigation au clavier / a la manette entre des elements places a l'ecran (logique pure, testable).
 *
 * items : [{ x, y }, ...] centres des elements ; from : index de l'element courant ;
 * dir : 'up' | 'down' | 'left' | 'right'. Retourne l'index de l'element voisin dans cette direction, ou `from`
 * s'il n'y en a pas (pas de rebouclage). Le voisin est le plus proche dans la direction demandee, avec une
 * penalite pour le decalage lateral : appuyer sur "bas" va vers l'element PLUS BAS le mieux aligne, pas vers
 * un element lointain en diagonale.
 */
export function pickNeighbor(pItems, pFrom, pDir) {
    const cur = pItems[pFrom];
    let best = pFrom, bestScore = Infinity;
    pItems.forEach((it, i) => {
        if (i === pFrom) return;
        const dx = it.x - cur.x, dy = it.y - cur.y;
        let along, across;
        if (pDir === 'up') { along = -dy; across = dx; }
        else if (pDir === 'down') { along = dy; across = dx; }
        else if (pDir === 'left') { along = -dx; across = dy; }
        else { along = dx; across = dy; }
        if (along <= 0) return; // pas dans cette direction
        const score = along + Math.abs(across) * 2;
        if (score < bestScore) { bestScore = score; best = i; }
    });
    return best;
}
