import { Container, Graphics, Text } from '../core/fff.js';
import { Config } from './Config.js';

/**
 * Voile de chargement : fond uni + message et barre de progression en bas de l'ecran.
 * C'est une simple vue : c'est le ScreenManager qui la pilote (fondu, progression), voir
 * ScreenManager.loadScreen().
 */
export class LoadingOverlay extends Container {
    constructor(pMessage = "Chargement...", pColor = 0x000000) {
        super();
        this.eventMode = 'static'; // bloque les clics vers l'ecran qui se charge derriere
        this._persistent = true;   // BaseScreen._disposeStage() ne le detruit pas au changement d'ecran

        const W = Config.STAGEWIDTH, H = Config.STAGEHEIGHT;
        const bg = new Graphics();
        bg.beginFill(pColor, 1);
        bg.drawRect(0, 0, W, H);
        bg.endFill();
        this.addChild(bg);

        this._text = new Text(pMessage, { fontFamily: Config.DEFAULT_FONT, fontSize: 22, fill: 0xFFD690, align: 'left' });
        this._text.position.set(40, H - 78);
        this.addChild(this._text);

        this._barX = 40;
        this._barY = H - 40;
        this._barW = W - 80;
        this._barH = 10;
        this._bar = new Graphics();
        this.addChild(this._bar);
        this.progress = 0;
    }

    set message(pValue) { this._text.text = pValue; }

    /** progression 0..1 */
    get progress() { return this._progress; }
    set progress(pValue) {
        this._progress = Math.max(0, Math.min(1, pValue));
        const g = this._bar;
        g.clear();
        g.lineStyle(1, 0xFFD690);
        g.drawRect(this._barX, this._barY, this._barW, this._barH);
        g.beginFill(0xFFD690);
        g.drawRect(this._barX + 2, this._barY + 2, (this._barW - 4) * this._progress, this._barH - 4);
        g.endFill();
    }
}
