import { Howl, Howler } from 'howler';
import { Config } from './Config.js';
import { Save } from '../core/Save.js';

/**
 * Sons du jeu : chaque fichier de assets/ n'est charge (et decode) qu'une seule fois,
 * puis joue autant de fois que necessaire.
 *
 *   SoundManager.play(SoundManager.CLICK);
 *   SoundManager.muted = true;
 */
export class SoundManager {
    constructor() { }

    // nom du fichier dans assets/ (sans extension)
    static get CLICK() { return "click1" }
    static get ERROR() { return "error" }
    static get GOOD() { return "good" }
    static get JUMP() { return "jump" }

    /**
     * Declare un son dont le fichier n'est pas assets/<nom>.ogg.
     * @param pName    nom utilise ensuite avec play() / stop()
     * @param pFile    chemin relatif a assets/ (avec extension : .wav, .mp3...)
     * @param pOptions options Howler : { loop: true, html5: true } pour une musique
     */
    static add(pName, pFile, pOptions = {}) {
        this._sounds[pName] = new Howl({ src: [Config.ASSETS_PATH + pFile], ...pOptions });
    }

    static _get(pName) {
        if (!this._sounds[pName]) {
            this._sounds[pName] = new Howl({ src: [Config.ASSETS_PATH + pName + ".ogg"] });
        }
        return this._sounds[pName];
    }

    /** Charge des sons a l'avance pour qu'ils soient prets au premier appel de play(). */
    static preload(...pNames) {
        pNames.forEach((name) => this._get(name));
    }

    /** @returns l'id de lecture Howler (utilisable avec stop, fade...) */
    static play(pName) {
        return this._get(pName).play();
    }

    /** Arrete un son (ou toutes ses lectures en cours). */
    static stop(pName) {
        if (this._sounds[pName]) this._sounds[pName].stop();
    }

    static get muted() { return this._muted }
    static set muted(pValue) {
        this._muted = !!pValue;
        Howler.mute(this._muted);
        Save.set('muted', this._muted);
    }

    // volume global entre 0 et 1
    static get volume() { return Howler.volume() }
    static set volume(pValue) {
        Howler.volume(pValue);
        Save.set('volume', Howler.volume());
    }
}

SoundManager._sounds = {};
SoundManager._muted = false;
