/**
 * Une touche logique, identifiee par son event.code (position physique, independante
 * de la disposition du clavier : 'KeyW' = Z sur AZERTY, W sur QWERTY).
 * Son etat est la combinaison de plusieurs sources : clavier, manette, boutons tactiles.
 */
export class Key {
    /**
     * @param code  valeur de KeyboardEvent.code
     * @param clock fonction qui renvoie le temps de jeu en secondes (fournie par GameInput) ;
     *              sert a dater les appuis pour l'input buffer
     */
    constructor(code, clock = () => performance.now() / 1000) {
        this.code = code;
        this._clock = clock;
        this._pressTime = -Infinity;
        this._releaseTime = -Infinity;
        this._pressConsumed = true;
        this._sources = { keyboard: false, pad: false, touch: false };
        this.press = undefined;
        this.release = undefined;

        this._onKeyDown = (event) => {
            if (event.code !== this.code) return;
            event.preventDefault();
            this.setSource("keyboard", true);
        };

        this._onKeyUp = (event) => {
            if (event.code !== this.code) return;
            event.preventDefault();
            this.setSource("keyboard", false);
        };

        // evite les touches "collees" quand la fenetre perd le focus
        this._onBlur = () => this.setSource("keyboard", false);

        document.addEventListener("keydown", this._onKeyDown, false);
        document.addEventListener("keyup", this._onKeyUp, false);
        window.addEventListener("blur", this._onBlur, false);
    }

    get isDown() {
        const s = this._sources;
        return s.keyboard || s.pad || s.touch;
    }

    get isUp() { return !this.isDown }

    // ---- input buffer -------------------------------------------------------------------------
    // Un appui est "memorise" : le jeu peut le lire quelques dizaines de ms APRES qu'il ait eu lieu
    // (ex : appui sur saut 80 ms avant de toucher le sol -> le saut part des l'atterrissage).
    // consumePress() empeche qu'un meme appui serve deux fois.

    /** secondes ecoulees depuis le dernier appui (Infinity si jamais appuyee) */
    get timeSincePress() { return this._clock() - this._pressTime; }

    /** secondes ecoulees depuis le dernier relachement */
    get timeSinceRelease() { return this._clock() - this._releaseTime; }

    /** vrai si un appui non consomme a eu lieu il y a moins de pWindow secondes */
    pressedWithin(pWindow) {
        return !this._pressConsumed && this.timeSincePress <= pWindow;
    }

    /** vrai si la touche a ete relachee il y a moins de pWindow secondes */
    releasedWithin(pWindow) {
        return this.timeSinceRelease <= pWindow;
    }

    /** consomme l'appui memorise ; renvoie vrai s'il y en avait un (dans la fenetre pWindow) */
    consumePress(pWindow = Infinity) {
        if (!this.pressedWithin(pWindow)) return false;
        this._pressConsumed = true;
        return true;
    }

    /** oublie l'appui memorise (ex : changement d'ecran) */
    clearBuffer() { this._pressConsumed = true; }

    setSource(pSource, pValue) {
        const wasDown = this.isDown;
        this._sources[pSource] = pValue;
        const isDown = this.isDown;

        if (!wasDown && isDown) {
            this._pressTime = this._clock();
            this._pressConsumed = false;
            if (this.press) this.press();
        } else if (wasDown && !isDown) {
            this._releaseTime = this._clock();
            if (this.release) this.release();
        }
    }

    destroy() {
        document.removeEventListener("keydown", this._onKeyDown, false);
        document.removeEventListener("keyup", this._onKeyUp, false);
        window.removeEventListener("blur", this._onBlur, false);
        this._sources = { keyboard: false, pad: false, touch: false };
    }
}