// Registre des demos. Chaque demo est lancee avec un parametre d'URL : index.html?demo=<id>
// Une demo = { id, title, screen (classe d'ecran de depart), assets, init() }
// Pour en ajouter une : creer son module `xxx.demo.js` et l'enregistrer ici (une ligne `when(...)`).
//
// __DEMO__ est injecte par Vite (voir vite.config.js) : 'all' (dev, build complet) ou l'id d'une demo
// quand on construit une seule demo (`npm run build -- --demo=1500`). Dans ce cas les autres lignes
// sont des conditions fausses a la compilation : leurs modules ne sont PAS inclus dans le build.
const DEMOS = {
    ...(__DEMO__ === 'all' || __DEMO__ === 'title' ? { title: () => import('./raycaster/title.demo.js').then((m) => m.title) } : {}),
    ...(__DEMO__ === 'all' || __DEMO__ === 'hex' ? { hex: () => import('./hex/demo.js').then((m) => m.hex) } : {}),
    ...(__DEMO__ === 'all' || __DEMO__ === 'raycaster' ? { raycaster: () => import('./raycaster/raycaster.demo.js').then((m) => m.raycaster) } : {}),
    ...(__DEMO__ === 'all' || __DEMO__ === '1500' ? { '1500': () => import('./1500/demo.js').then((m) => m.demo1500) } : {}),
};

// demo lancee quand l'URL n'en precise pas ; dans un build mono-demo, c'est forcement celle-la
export const DEFAULT_DEMO = __DEMO__ === 'all' ? 'title' : __DEMO__;

export function demoIds() {
    return Object.keys(DEMOS);
}

// id de la demo demandee dans l'URL (?demo=hex), ou la demo par defaut
export function demoIdFromUrl() {
    if (__DEMO__ !== 'all') return __DEMO__; // build mono-demo : l'URL est ignoree
    const id = new URLSearchParams(location.search).get('demo');
    if (id === null) return DEFAULT_DEMO;
    if (!(id in DEMOS)) {
        console.warn(`Demo inconnue "${id}" (demos disponibles : ${demoIds().join(', ')}). Format de l'URL : ?demo=<id>`);
        return DEFAULT_DEMO;
    }
    return id;
}

export function loadDemo(id) {
    return DEMOS[id]();
}
