import { ScreenManager } from './ScreenManager.js';
import { PIXI } from '../lib/pixi.js';
import { GameInput } from './GameInput.js';
import { MsgBox } from './MsgBox.js';
import { Config } from './Config.js';

// static class
export class BT {
	constructor() { }

	// asynchrone depuis Pixi 8 : `await BT.init(...)`
	static async init(pDomTarget) {
		this._domContainer = pDomTarget;

		let app = new PIXI.Application();
		await app.init({
			width: Config.STAGEWIDTH,
			height: Config.STAGEHEIGHT,
			antialias: true,
			backgroundColor: Config.DEFAULT_STAGECOLOR,
			resolution: 1
		});

		pDomTarget.appendChild(app.canvas);
		this._app = app;
		this._stage = app.stage;
		this._snapshot = undefined;
		this._ticker = new PIXI.Ticker();
		this._gameInputs = [];
	}

	static get version() { return Config.VERSION }
	static get stage() { return this._stage }
	static get app() { return this._app }
	static get ticker() { return this._ticker }
	static get domContainer() { return this._domContainer }
	static get stageColor() { return this.app.renderer.background.color.toNumber() }

	static get dc() { return this._dc }
	static set dc(value) { this._dc = value }
	static set stageColor(newColor = 0xCC00CC) {
		this.app.renderer.background.color = newColor;
	}

	static getGameInput(player_id = 1) {
		if (!this._gameInputs[player_id - 1]) {
			this._gameInputs[player_id - 1] = new GameInput(player_id - 1);
		}

		return this._gameInputs[player_id - 1];
	}

	static get currentScreen() { return ScreenManager.current }

	// HELPERS

	//////////////////////////////////////////////////////
	// RANDOM
	/**
	 * [Shuffle an array -- modifiying the original]
	 * @param  arr [the array]
	 * @return     [the shuffled array]
	 */
	static shuffle(arr) {
		let i, p, tmp;
		for (i = arr.length - 1; i > 0; --i) {
			p = (Math.random() * (i + 1)) >> 0;
			if (p === i) {
				continue;
			}
			tmp = arr[i];
			arr[i] = arr[p];
			arr[p] = tmp;
		}
	}

	/**
	 * [Shuffle an array -- not modifying the original]
	 * @param  a [the array]
	 * @return   [the new Array]
	 */
	static randomSpliceShuffle(a) {
		let _source = a.concat(), // clone
			n = _source.length,
			i = 0, m, r,
			tmp = new Array(n);

		while (i < n) {
			if (!tmp[i]) {
				m = _source.length;
				r = (Math.random() * m) >> 0;
				tmp[i] = _source[r];
				_source.splice(r, 1);
			}
			i++;
		}

		return tmp;
	};

	static getRandomInt(min, max) {
		return Math.floor(Math.random() * (max - min + 1)) + min;
	}

	static getRandomFloat(min, max) {
		return Math.random() * (max - min) + min;
	}

	static getRandomPoint(minX = 0, maxX = Config.STAGEWIDTH, minY = 0, maxY = Config.STAGEHEIGHT) {
		return new PIXI.Point(this.getRandomInt(minX, maxX), this.getRandomInt(minY, maxY));
	}

	// linear congruential generator (LCG)
	// https://en.wikipedia.org/wiki/Linear_congruential_generator
	static createSeededGenerator(seed) {
		class Ran {
			constructor(seed) {
				this.m = 134456;
				this.a = 8121; // a - 1 should be divisible by m's prime factors
				this.c = 28411; // c and m should be co-prime

				this.z = seed || 100;

				this.next();
			}

			next() {
				this.z = (this.a * this.z + this.c) % this.m;
				return this.z / this.m;
			}
		}

		return new Ran(seed);
	};

	/**
	 * 2D Quasi random number between 0..1
	 */
	static plastic(index) {
		const p1 = 0.7548776662466927; // inverse of plastic number
		const p2 = 0.5698402909980532;
		return { x: (p1 * index) % 1, y: (p2 * index) % 1 };
	}

	/**
	 * 1D Quasi random between 0..1
	 */
	static golden(index) {
		const p = 0.6180339887498949; // inverse of golden ratio
		return p * index % 1;
	}

	//////////////////////////////////////////////////////////
	// FORMATTING

	/**
	 * [pad0 ex : change 56 to 0056]
	 * @param  str [the original string value]
	 * @return     [padded string value]
	 */
	static pad0(pStr, NUM = 4) {
		while (pStr.length < NUM) {
			pStr = '0' + pStr;
		}

		return pStr;
	};

	/**
	 * Format MM:SS
	 * @param  pSeconds the number you want to format
	 * @return         a String MM:SS filled with 0 when valus are under 10
	 */
	static ftime(pSeconds) {
		var min = (pSeconds / 60) >> 0,
			sec;

		if (min < 10) {
			min = "0" + min;
		}
		sec = pSeconds % 60;
		if (sec < 10) {
			sec = "0" + sec;
		}

		return min + ":" + sec;
	};

	//////////////////////////////////////////////////////////
	// FILTERS

	/**
	 * return a sorted copy of the original array
	 * note : by default js sort() on string which can lead to issues with negative numbers
	 * @param {*} flatArray
	 */
	static numericSort(flatArray) {
		return flatArray.concat().sort((a, b) => a - b)
	}

	/**
	 * remove duplicate values from an array (without sorting)
	 * @param flatArray Array filled with litterals
	 * @return a new array filled with unique values.
	 *
	 * example
	 * var arr = [1,45,"1",2,"9",1];
	 * will return [1, 45, "1", 2, "9"]
	 */
	static filterDuplicateValues(flatArray) {
		return flatArray.filter(function (elem, index, self) { return index === self.indexOf(elem); });
	};

	/**
	 * remove duplicate objects from an array (without sorting) based on a key value.
	 * @param  flatArray your flat array
	 * @param  key       the on which you want filter your object
	 * @return           a new array filled only with unique values
	 */
	static filterDuplicateObjects(flatArray, key) {
		var filteredArray = [],
			unique = {};

		flatArray.forEach(function (node) {
			if (!unique[node[key]]) {
				filteredArray.push(node);
				unique[node[key]] = node;
			}
		});

		return filteredArray;
	};

	//////////////////////////////////////////////////////////
	// MATHS

	/**
	 * [distance description]
	 * @param  p0 Point object
	 * @param  p1 Point object
	 * @return    distance between points
	 */
	static distance(p0, p1) {
		let dx = p1.x - p0.x,
			dy = p1.y - p0.y;

		return Math.sqrt(dx * dx + dy * dy);
	};

	/**
	 * [getShortRotation description]
	 * @param  angle1 in degres
	 * @param  angle2 in degres
	 * @return        the smallest angle
	 */
	static getShortRotation(angle1, angle2) {
		return ((angle1 - angle2 + 540) % 360) - 180;
	};

	/**
	 * [clamp description]
	 * @param  value [input]
	 * @param  min   min
	 * @param  max   max
	 * @param  loop  if exceed use 'the rest' for another iteration
	 * @return       return clamped value
	 */
	static clamp(value, min, max, loop = false) {
		if (loop === true) {
			if (value < min) {
				return max - ((min - value) % (max - min));
			}
			if (value > max) {
				return min + ((value - max) % (max - min));
			}
		}

		return Math.max(Math.min(value, max), min);
	};

	/**
	 * [map description]
	 * @param n 			[description]
	 * @param start1 		[description]
	 * @param stop1 		[description]
	 * @param start2 		[description]
	 * @param stop2 		[description]
	 * @param withinBounds	[description]
	 * @return       		[description]
	 */
	static map(n, start1, stop1, start2, stop2, withinBounds) {
		var newval = (n - start1) / (stop1 - start1) * (stop2 - start2) + start2;
		if (!withinBounds) {
			return newval;
		}

		if (start2 < stop2) {
			return this.clamp(newval, start2, stop2);
		} else {
			return this.clamp(newval, stop2, start2);
		}
	}

	/**
	 * [Smootstep description]
	 * @param {*} x
	 * @param {*} e0
	 * @param {*} e1
	 */
	static smoothstep(x, e0 = 0, e1 = 1) {
		x = Math.min(Math.max((x - e0) / (e1 - e0), 0.0), 1.0);
		return x * x * (3 - 2 * x);
	}

	/**
	 * [Smootstep description]
	 * @param {*} x
	 * @param {*} e0
	 * @param {*} e1
	 */
	static smoothstep2(x, e0 = 0, e1 = 1) {
		// Scale, bias and saturate x to 0..1 range
		x = Math.min(Math.max((x - e0) / (e1 - e0), 0.0), 1.0);
		// Evaluate polynomial
		return x * x * x * (x * (x * 6 - 15) + 10);
	}

	/**
	 * Linear interpolation (LERP)
	 * @param {*} a start value
	 * @param {*} b end value
	 * @param {*} amount
	 */
	static mix(a, b, amount) {
		return (1 - amount) * a + amount * b;
	}

	/**
	 * Normalisation
	 * @param {*} pValue 
	 * @param {*} pMin 
	 * @param {*} pMax 
	 * @returns 
	 */
	static normalize(pValue, pMin, pMax){
		return (pValue - pMin) / (pMax - pMin);
	}

	//////////////////////////////////////////////////////////
	// OTHERS

	static createMessageBox(pFlag, pTitle, pText, pPosition) {
		return new MsgBox(pFlag, pTitle, pText);
	}

	/**
	 * usage
	 * BT.sleep(500).then(() => {  });
	 * @param {*} timeMs
	 */
	static sleep(timeMs) {
		return new Promise((resolve) => setTimeout(resolve, timeMs));
	}


	/**
	 * copie les pixels d'un objet Graphics pour en faire une texture utilisable par un Sprite
	 * @param {*} graphic copy les pixels d'un Graphics
	 * @param {*} scalemode 'linear' | 'nearest'
	 * @param {*} resolution 1
	 *
	 * return Texture
	 */
	static copyPixels(graphic, scalemode = 'linear', resolution = 1) {
		graphic.x = graphic.width * .5;
		graphic.y = graphic.height * .5;

		let renderTexture = PIXI.RenderTexture.create({ width: graphic.width, height: graphic.height, scaleMode: scalemode, resolution: resolution });
		this.app.renderer.render({ container: graphic, target: renderTexture });

		return renderTexture;
	}

	static snap(graphic) {
		this._snapshot = PIXI.RenderTexture.create({ width: graphic.width, height: graphic.height });
		this.app.renderer.render({ container: graphic, target: this._snapshot });

		return this._snapshot;
	}

	/**
	 * [getUniformResolution description]
	 * return vec2
	 */
	static getUniformResolution() {
		return [Config.STAGEWIDTH, Config.STAGEHEIGHT];
	}

	/**
	 * [isMobile description]
	 * return bool
	 */
	static isMobile() {
		return PIXI.isMobile.any;
	}

}

// static properties of the class are defined outside and after the class -- lol ES6
BT._domContainer = undefined;
BT._stage = undefined;
BT._dc = undefined; 	// debug console reference
BT._app = undefined;
BT._ticker = undefined;