export class MessageEvent {
    constructor(pMessageEventType, pDatas = undefined) {
        this._messageEventType = pMessageEventType;
        this._datas = pDatas;
    }

    get messageEventType() { return this._messageEventType }
    get datas() { return this._datas }
}

// core message events
MessageEvent.ON_BLUR = "blur"; // native window event
MessageEvent.SCREEN_RESUMED = "messageevent::screen_resumed"
MessageEvent.SCREEN_START = "messageevent::screen_start";
MessageEvent.SCREEN_DESTROYED = "messageevent::screen_destroyed";
MessageEvent.MSG_BOX = "messageevent::message-box";
