import { PIXI } from '../lib/pixi.js';
import { Sprite } from '../core/fff.js';
import { BT } from './BT.js';
import { BaseScreen } from './BaseScreen.js';
import { Config } from './Config.js';
import { Datas } from './Datas.js';
import { PreloadBar } from './PreloadBar.js';

// assets communs a toutes les demos : [cle dans Datas.atlas, fichier, 'sprite' si partage sous forme de Sprite]
const BASE_ASSETS = [
    [Datas.BACKGROUND_IMAGE, 'Fond.png', 'sprite'],

    [Datas.METAL_PANEL, 'ui/metalPanel.png'],

    [Datas.MESSAGE_BOX, 'ui/Dialog.png', 'sprite'],
    [Datas.MESSAGE_BOX_EXCLAMATION, 'pictos/exclamation.png'],
    [Datas.MESSAGE_BOX_INFORMATION, 'pictos/information.png'],
    [Datas.MESSAGE_BOX_WARNING, 'pictos/warning.png'],
    [Datas.MESSAGE_BOX_QUESTION, 'pictos/question.png'],

    [Datas.BUTTON_WHITE_L, 'ui/barHorizontal_white_left.png'],
    [Datas.BUTTON_WHITE_M, 'ui/barHorizontal_white_mid.png'],
    [Datas.BUTTON_WHITE_R, 'ui/barHorizontal_white_right.png']
];

export class Preload extends BaseScreen {
    constructor() {
        super();
    }

    start() {
        // la demo a lancer est fournie par Main : { screen, assets, init }
        const demo = Preload.demo;
        this._nextScreen = demo.screen;
        super.start();

        this.visible = true;

        let preloadBar = new PreloadBar();
        this.stage.addChild(preloadBar);

        // pixel art : pas de lissage sur les textures chargees ensuite
        PIXI.TextureStyle.defaultOptions.scaleMode = 'nearest';

        const assets = [...BASE_ASSETS, ...demo.assets];
        assets.forEach(([key, file]) => PIXI.Assets.add({ alias: key, src: Config.ASSETS_PATH + file }));

        PIXI.Assets.load(assets.map(([key]) => key)).then((textures) => {
            assets.forEach(([key, , type]) => {
                Datas.atlas[key] = type === 'sprite' ? new Sprite(textures[key]) : textures[key];
            });

            if (demo.init) demo.init();

            BT.sleep(750).then(() => {
                this.end();
            });
        });
    }

}

// demo courante, definie par Main avant de lancer l'ecran Preload
Preload.demo = undefined;
