export class Gamepad {
    constructor(pIndex = 0) {
        this._index = pIndex;
        this._connected = false;

        this._onConnected = (event) => {
            if (event.gamepad.index === this._index) this._connected = true;
        };
        this._onDisconnected = (event) => {
            if (event.gamepad.index === this._index) this._connected = false;
        };

        window.addEventListener("gamepadconnected", this._onConnected, false);
        window.addEventListener("gamepaddisconnected", this._onDisconnected, false);
    }

    // l'objet natif (snapshot de l'etat) ou null
    get pad() {
        const pads = navigator.getGamepads ? navigator.getGamepads() : [];
        return pads[this._index] || null;
    }

    get isActive() {
        return this._connected && this.pad !== null;
    }

    isPressed(pButtonIndex) {
        const pad = this.pad;
        return !!(pad && pad.buttons[pButtonIndex] && pad.buttons[pButtonIndex].pressed);
    }
}