/**
 * Compteur de performance : FPS, temps de frame moyen et pire temps (les a-coups).
 *
 *   FpsMeter.install()        // dans Main : active avec ?fps dans l'URL, bascule avec la touche F3
 *   meter.push(ms)            // a appeler a chaque frame avec ticker.elapsedMS (temps reel)
 *
 * Les stats sont calculees sur une fenetre d'environ 0.5 s. Le pire temps de frame est plus parlant que
 * la moyenne pour comparer PC / A1200 : 60 fps de moyenne avec une frame a 80 ms, c'est un a-coup visible.
 * Le calcul (FpsMeter) ne depend pas du DOM ; l'affichage (install) est un petit <div> a part.
 */
import { Fullscreen } from './Fullscreen.js';

export class FpsMeter {
    constructor(pWindow = 0.5) {
        this.window = pWindow;       // secondes entre deux mises a jour des stats
        this.fps = 0;
        this.avg = 0;                // ms
        this.worst = 0;              // ms
        this._sum = 0;
        this._frames = 0;
        this._worst = 0;
    }

    /** @returns true quand les stats viennent d'etre recalculees */
    push(pMs) {
        this._sum += pMs;
        this._frames++;
        if (pMs > this._worst) this._worst = pMs;
        if (this._sum < this.window * 1000) return false;
        this.fps = this._frames * 1000 / this._sum;
        this.avg = this._sum / this._frames;
        this.worst = this._worst;
        this._sum = 0; this._frames = 0; this._worst = 0;
        return true;
    }

    toString() {
        return this.fps.toFixed(0) + " fps  " + this.avg.toFixed(1) + " ms  pire " + this.worst.toFixed(1) + " ms";
    }

    /** cree le compteur et son affichage ; retourne l'objet avec update(ms) a appeler a chaque frame */
    static install() {
        const meter = new FpsMeter();
        const el = document.createElement("div");
        el.style.cssText = "position:fixed;top:4px;right:4px;z-index:10;padding:2px 6px;font:12px monospace;" +
            "color:#0f0;background:rgba(0,0,0,.6);pointer-events:none;display:none";
        document.body.appendChild(el);

        const toggle = (pOn) => {
            meter.enabled = pOn !== undefined ? pOn : !meter.enabled;
            el.style.display = meter.enabled ? "block" : "none";
            meter.fps = 0;
        };
        meter.enabled = false;
        meter.update = (pMs) => {
            if (!meter.enabled) return;
            if (meter.push(pMs)) {
                el.textContent = meter.toString();
                el.style.color = meter.worst > 33 ? "#f80" : "#0f0";
            }
        };
        meter.toggle = toggle;
        toggle(new URLSearchParams(window.location.search).has("fps"));
        // en plein ecran seul l'element plein ecran (gameContainer) est affiche : on y deplace le compteur
        Fullscreen.onChange(() => Fullscreen.host.appendChild(el));
        window.addEventListener("keydown", (e) => {
            if (e.key === "F3") { e.preventDefault(); toggle(); }
        });
        return meter;
    }
}
