import { Graphics } from '../core/fff.js';
import { pickNeighbor } from './MenuFocus.js';

/**
 * Navigation de menu au clavier / a la manette pour des boutons Pixi (BaseButton, ButtonScale3...).
 * haut / bas / gauche / droite deplacent le focus (cadre orange qui clignote), action1 valide.
 * La souris reste utilisable : survoler un bouton lui donne le focus.
 *
 *   // en general via l'ecran : this.menu (BaseScreen)
 *   this.menu.show([btnJouer, btnQuitter]);   // modal : les touches ne vont plus au jeu
 *   this.menu.hide();                          // rend les entrees au jeu
 *
 * Valider "clique" le bouton : pointerdown, pointerup, pointertap et click sont emis (comme avec la souris),
 * donc les ecouteurs existants (on('click'), BaseButton.POINTER_UP...) fonctionnent sans changement.
 * Les MsgBox de BaseScreen.showMessageBox s'en servent automatiquement.
 */
export class MenuNavigator {
    constructor(pScreen) {
        this.screen = pScreen;
        this.items = [];
        this.index = 0;
        this.active = false;
        this._savedTarget = null;
        this._time = 0;
        this._marker = null;
        this._hoverHandlers = [];
    }

    get focused() { return this.items[this.index] || null; }

    /** active le menu sur ces boutons ; coupe les entrees du jeu (modal) tant qu'il est affiche */
    show(pButtons, pFocus = 0) {
        this.hide();
        if (!pButtons.length) return;
        this.items = pButtons.slice();
        this.active = true;
        const gi = this.screen.gameInput1;
        this._savedTarget = gi.target;
        gi.target = null;
        gi.keyboard.forEach((k) => k.clearBuffer()); // un appui d'avant l'ouverture ne doit pas valider
        this.items.forEach((b) => {
            const over = () => this._setFocus(this.items.indexOf(b));
            b.on('pointerover', over);
            this._hoverHandlers.push([b, over]);
        });
        this._setFocus(Math.min(pFocus, this.items.length - 1));
    }

    hide() {
        if (!this.active) return;
        this._removeMarker();
        this._hoverHandlers.forEach(([b, fn]) => b.off('pointerover', fn));
        this._hoverHandlers = [];
        this.items = [];
        this.active = false;
        const gi = this.screen.gameInput1;
        // on ne rend la cible que si personne d'autre ne l'a prise entre-temps (changement d'ecran...)
        if (gi.target === null) gi.target = this._savedTarget;
        this._savedTarget = null;
    }

    /** a appeler a chaque frame (fait par ScreenManager) */
    update(pDt) {
        if (!this.active) return;
        this._time += pDt;
        const gi = this.screen.gameInput1;
        for (const dir of ['up', 'down', 'left', 'right']) {
            if (gi[dir].consumePress(0.15)) this._move(dir);
        }
        if (gi.action1.consumePress(0.15)) this._activate();
        if (this._marker) this._marker.alpha = 0.55 + 0.45 * Math.sin(this._time * 8);
    }

    _move(pDir) {
        const pts = this.items.map((b) => {
            const g = b.getGlobalPosition();
            return { x: g.x, y: g.y };
        });
        this._setFocus(pickNeighbor(pts, this.index, pDir));
    }

    _setFocus(pIndex) {
        if (pIndex < 0 || pIndex >= this.items.length) return;
        this._removeMarker();
        this.index = pIndex;
        const b = this.items[pIndex];
        const r = b.getLocalBounds();
        const m = this._marker = new Graphics();
        m.lineStyle(3, 0xE8590C);
        m.drawRect(r.x - 3, r.y - 3, r.width + 6, r.height + 6);
        m.eventMode = 'none';
        b.addChild(m);
    }

    _removeMarker() {
        if (this._marker) {
            if (this._marker.parent) this._marker.parent.removeChild(this._marker);
            this._marker.destroy();
            this._marker = null;
        }
    }

    _activate() {
        const b = this.focused;
        if (!b) return;
        // simule un clic complet ; le menu peut se fermer pendant l'un des evenements
        const ev = { currentTarget: b, target: b };
        ['pointerdown', 'pointerup', 'pointertap', 'click'].forEach((name) => b.emit(name, ev));
    }
}
