import { Save } from '../core/Save.js';
import { ScreenManager } from './ScreenManager.js';
import { Fullscreen } from './Fullscreen.js';
import { SoundManager } from './SoundManager.js';
import { assignKey, isReserved, keyLabel } from './KeyLayout.js';

/**
 * Panneau d'options superpose au jeu (DOM), identique dans toutes les demos.
 * Ouverture : touche F1 ou bouton d'engrenage ; fermeture : Echap ou bouton Fermer.
 * Pendant qu'il est ouvert l'ecran courant est fige et les entrees du jeu coupees.
 *
 *   OptionsPanel.install({ gameInput: BT.getGameInput(1), fps: fpsMeter, demoId: 'raycaster' });
 *
 * Contenu : volume et mute (SoundManager), compteur de FPS, remappage des 7 touches (disposition sauvee par
 * demo : "keys:<demoId>"), reinitialisation de la sauvegarde. Les reglages sont ecrits dans Save a chaque changement.
 */
export class OptionsPanel {
    static install(pOptions) {
        if (OptionsPanel._root) return;
        const gi = OptionsPanel._gi = pOptions.gameInput;
        OptionsPanel._fps = pOptions.fps;
        OptionsPanel._keysKey = 'keys:' + (pOptions.demoId || 'default');
        OptionsPanel._capturing = -1;

        const css = (el, s) => { el.style.cssText = s; return el; };
        const mk = (tag, style, text) => {
            const el = css(document.createElement(tag), style || '');
            if (text !== undefined) el.textContent = text;
            return el;
        };
        const btnStyle = 'padding:4px 10px;font:13px monospace;cursor:pointer;margin:2px';

        // ---- bouton d'engrenage  ----
        const gear = OptionsPanel._gear = mk('button', 'position:fixed;top:4px;left:4px;z-index:20;width:40px;height:40px;' +
            'font-size:22px;cursor:pointer;border:2px solid #777;border-radius:6px;background:#ddd', '⚙');
        gear.title = 'Options (F1)';
        gear.onclick = () => OptionsPanel.toggle();

        // ---- panneau ----
        const root = OptionsPanel._root = mk('div', 'position:fixed;inset:0;z-index:900;display:none;background:rgba(0,0,0,.75);' +
            'color:#fff;font:14px monospace;overflow:auto');
        const box = mk('div', 'max-width:460px;margin:24px auto;padding:16px 20px;background:#222;border:2px solid #888;border-radius:8px');
        root.appendChild(box);
        box.appendChild(mk('div', 'font-size:20px;margin-bottom:12px', 'Options'));

        const section = (title) => box.appendChild(mk('div', 'margin:14px 0 6px;color:#9cf;border-bottom:1px solid #555', title));

        // son
        section('Son');
        const volRow = box.appendChild(mk('div', 'margin:4px 0'));
        volRow.appendChild(mk('span', '', 'Volume '));
        const vol = OptionsPanel._vol = mk('input');
        vol.type = 'range'; vol.min = 0; vol.max = 100; vol.style.verticalAlign = 'middle';
        vol.oninput = () => { SoundManager.volume = vol.value / 100; volLabel.textContent = vol.value + ' %'; };
        const volLabel = mk('span', 'margin-left:8px');
        volRow.append(vol, volLabel);
        const muteRow = box.appendChild(mk('label', 'display:block;margin:4px 0;cursor:pointer'));
        const mute = OptionsPanel._mute = mk('input');
        mute.type = 'checkbox';
        mute.onchange = () => { SoundManager.muted = mute.checked; };
        muteRow.append(mute, document.createTextNode(' Couper le son'));

        // affichage
        section('Affichage');
        const fpsRow = box.appendChild(mk('label', 'display:block;margin:4px 0;cursor:pointer'));
        const fpsBox = OptionsPanel._fpsBox = mk('input');
        fpsBox.type = 'checkbox';
        fpsBox.onchange = () => {
            if (OptionsPanel._fps) OptionsPanel._fps.toggle(fpsBox.checked);
            Save.set('fps', fpsBox.checked);
        };
        fpsRow.append(fpsBox, document.createTextNode(' Afficher les FPS (F3 pour l\'afficher a tout moment)'));
        if (Fullscreen.isSupported) {
            const fsRow = box.appendChild(mk('label', 'display:block;margin:4px 0;cursor:pointer'));
            const fsBox = OptionsPanel._fsBox = mk('input');
            fsBox.type = 'checkbox';
            fsBox.onchange = () => { fsBox.checked ? Fullscreen.enter() : Fullscreen.exit(); };
            fsRow.append(fsBox, document.createTextNode(' Plein ecran'));
        }

        // touches
        section('Touches');
        const labels = ['Haut', 'Bas', 'Gauche', 'Droite', 'Action 1', 'Action 2', 'Action 3'];
        OptionsPanel._keyBtns = labels.map((label, i) => {
            const row = box.appendChild(mk('div', 'display:flex;justify-content:space-between;align-items:center;margin:2px 0'));
            row.appendChild(mk('span', '', label));
            const b = mk('button', btnStyle + ';min-width:130px');
            b.onclick = () => OptionsPanel._startCapture(i);
            row.appendChild(b);
            return b;
        });
        const keyMsg = OptionsPanel._keyMsg = box.appendChild(mk('div', 'color:#fa0;min-height:18px;margin-top:4px'));
        const defKeys = mk('button', btnStyle, 'Touches par defaut');
        defKeys.onclick = () => {
            Save.set(OptionsPanel._keysKey, null);
            gi.setUserLayout(null);
            OptionsPanel._refreshKeys();
            keyMsg.textContent = 'Touches de la demo restaurees.';
        };
        box.appendChild(defKeys);

        // sauvegarde
        section('Sauvegarde');
        const reset = mk('button', btnStyle, 'Reinitialiser la sauvegarde');
        reset.onclick = () => {
            if (!OptionsPanel._confirmReset) {
                OptionsPanel._confirmReset = true;
                reset.textContent = 'Confirmer : tout effacer ?';
                reset.style.background = '#c33';
                return;
            }
            Save.reset();
            window.location.reload();
        };
        box.appendChild(reset);

        const close = mk('button', btnStyle + ';margin-top:16px;display:block', 'Fermer (Echap)');
        close.onclick = () => OptionsPanel.close();
        box.appendChild(close);

        document.body.append(gear, root);

        // plein ecran : seul l'element plein ecran est visible, on y deplace bouton et panneau
        Fullscreen.onChange(() => {
            Fullscreen.host.append(gear, root);
            if (OptionsPanel._fsBox) OptionsPanel._fsBox.checked = Fullscreen.isActive; // F11 / Echap peuvent aussi changer l'etat
        });

        // clavier : en phase de capture pour passer AVANT les touches du jeu
        window.addEventListener('keydown', (e) => OptionsPanel._onKey(e), true);
        OptionsPanel._reset = () => { OptionsPanel._confirmReset = false; reset.textContent = 'Reinitialiser la sauvegarde'; reset.style.background = ''; };
    }

    static get isOpen() { return OptionsPanel._root && OptionsPanel._root.style.display !== 'none'; }

    static toggle() { OptionsPanel.isOpen ? OptionsPanel.close() : OptionsPanel.open(); }

    static open() {
        if (!OptionsPanel._root || OptionsPanel.isOpen || ScreenManager.loading) return;
        const screen = ScreenManager.current;
        // fige l'ecran et coupe les entrees ; on garde l'etat precedent pour le restaurer
        OptionsPanel._saved = { screen, frozen: screen ? screen.frozen : false, target: OptionsPanel._gi.target };
        if (screen) screen.frozen = true;
        OptionsPanel._gi.target = null;

        OptionsPanel._vol.value = Math.round(SoundManager.volume * 100);
        OptionsPanel._vol.oninput();
        OptionsPanel._mute.checked = SoundManager.muted;
        OptionsPanel._fpsBox.checked = !!(OptionsPanel._fps && OptionsPanel._fps.enabled);
        if (OptionsPanel._fsBox) OptionsPanel._fsBox.checked = Fullscreen.isActive;
        OptionsPanel._keyMsg.textContent = '';
        OptionsPanel._reset();
        OptionsPanel._refreshKeys();
        OptionsPanel._root.style.display = 'block';
    }

    static close() {
        if (!OptionsPanel.isOpen) return;
        OptionsPanel._stopCapture();
        OptionsPanel._root.style.display = 'none';
        const s = OptionsPanel._saved;
        if (s) {
            // si l'ecran a change entre-temps (ne devrait pas arriver, il est fige), on ne touche a rien
            if (s.screen && ScreenManager.current === s.screen) {
                s.screen.frozen = s.frozen;
                OptionsPanel._gi.target = s.target;
            }
            OptionsPanel._saved = null;
        }
    }

    static _refreshKeys() {
        const layout = OptionsPanel._gi.layout;
        OptionsPanel._keyBtns.forEach((b, i) => {
            b.textContent = OptionsPanel._capturing === i ? 'Appuie sur une touche...' : keyLabel(layout[i]);
            b.style.background = OptionsPanel._capturing === i ? '#fa0' : '';
        });
    }

    static _startCapture(pIndex) {
        OptionsPanel._capturing = pIndex;
        OptionsPanel._keyMsg.textContent = 'Echap pour annuler.';
        OptionsPanel._refreshKeys();
    }

    static _stopCapture() {
        OptionsPanel._capturing = -1;
        OptionsPanel._refreshKeys();
    }

    static _onKey(e) {
        if (e.code === 'F1') {
            e.preventDefault(); e.stopImmediatePropagation();
            OptionsPanel.toggle();
            return;
        }
        if (!OptionsPanel.isOpen) return;

        // panneau ouvert : le jeu ne recoit aucune touche
        e.stopImmediatePropagation();
        if (e.code === 'F2' || e.code === 'F3' || e.code === 'F5' || e.code === 'F11' || e.code === 'F12') return; // outils du navigateur / compteur
        e.preventDefault();

        if (OptionsPanel._capturing >= 0) {
            if (e.code === 'Escape') {
                OptionsPanel._keyMsg.textContent = '';
                OptionsPanel._stopCapture();
            } else if (isReserved(e.code)) {
                OptionsPanel._keyMsg.textContent = 'Cette touche est reservee.';
            } else {
                const gi = OptionsPanel._gi;
                const layout = assignKey(gi.layout, OptionsPanel._capturing, e.code);
                const swapped = gi.layout.indexOf(e.code) !== -1 && gi.layout.indexOf(e.code) !== OptionsPanel._capturing;
                gi.setUserLayout(layout);
                Save.set(OptionsPanel._keysKey, layout);
                OptionsPanel._keyMsg.textContent = swapped ? 'Touche deja utilisee : les deux actions ont ete echangees.' : '';
                OptionsPanel._stopCapture();
            }
        } else if (e.code === 'Escape') {
            OptionsPanel.close();
        }
    }
}

OptionsPanel._root = null;
