import { SoundManager } from './SoundManager.js';
import { Container, Sprite, Text, bindPointerHandlers } from '../core/fff.js';
import { Config } from './Config.js';
import { Datas } from './Datas.js';

export class ButtonScale3 extends Container {
    constructor(pText, pX = 0, pY = 0, fixedWidth = 0) {
        super();

        this.oriX = pX;
        this.oriY = pY;

        this.x = pX;
        this.y = pY;

        this.label = pText;

        this.eventMode = 'static';
        this.cursor = 'pointer';
        bindPointerHandlers(this);
        this.state = 1;

        let text = new Text(" " + pText + " ", { fontFamily: Config.VECTOR_FUTURE_FONT, fontSize: 16, fill: Config.style.PRIMARY_DARK, align: 'center', dropShadowAngle: Math.PI / 2 });
        text.anchor.set(.5, .5);
        text.position.x = 2;

        let center = this.center = new Sprite(Datas.atlas[Datas.BUTTON_WHITE_M]);
        center.anchor.x = center.anchor.y = .5;
        center.width = (fixedWidth > 0) ? fixedWidth : Math.ceil(text.width);

        let left = new Sprite(Datas.atlas[Datas.BUTTON_WHITE_L]);
        left.anchor.set(.5, .5);
        left.position.set(-center.width / 2, 0);

        let right = new Sprite(Datas.atlas[Datas.BUTTON_WHITE_R]);
        right.anchor.set(.5, .5);
        right.position.set(center.width / 2, 0);

        this.addChild(center);
        this.addChild(right);
        this.addChild(left);

        this.addChild(text);
    }

    pointerdown(pEvent) {
        pEvent.currentTarget.y = this.oriY + 2;
        SoundManager.play(SoundManager.CLICK);
    };

    pointerup(pEvent) {
        pEvent.currentTarget.y = this.oriY;
    };

    pointerupoutside(pEvent) {
        pEvent.currentTarget.y = this.oriY;
    };
}