/**
 * Plein ecran : on met #gameContainer en plein ecran (pas toute la page), avec les prefixes des anciens navigateurs.
 *
 *   Fullscreen.toggle();            // doit etre appele depuis un clic ou une touche (regle des navigateurs)
 *   Fullscreen.isActive;            // vrai si le jeu est en plein ecran
 *   Fullscreen.onChange(() => ...); // appele a chaque entree / sortie (y compris par F11 ou Echap)
 *
 * Seul l'element plein ecran est affiche : tout ce qui doit rester visible (compteur FPS, options) doit etre
 * deplace dans Fullscreen.host pendant le plein ecran.
 */
export class Fullscreen {
    static get element() { return document.getElementById('gameContainer'); }

    /** element plein ecran actuel, sinon document.body : l'endroit ou ajouter les surcouches DOM */
    static get host() { return document.fullscreenElement || document.webkitFullscreenElement || document.body; }

    static get isSupported() {
        return !!(document.fullscreenEnabled || document.webkitFullscreenEnabled);
    }

    static get isActive() {
        return !!(document.fullscreenElement || document.webkitFullscreenElement);
    }

    static enter() {
        const el = Fullscreen.element;
        if (!el || Fullscreen.isActive) return;
        if (el.requestFullscreen) el.requestFullscreen();
        else if (el.webkitRequestFullscreen) el.webkitRequestFullscreen();
    }

    static exit() {
        if (!Fullscreen.isActive) return;
        if (document.exitFullscreen) document.exitFullscreen();
        else if (document.webkitExitFullscreen) document.webkitExitFullscreen();
    }

    static toggle() { Fullscreen.isActive ? Fullscreen.exit() : Fullscreen.enter(); }

    static onChange(pFn) {
        document.addEventListener('fullscreenchange', pFn);
        document.addEventListener('webkitfullscreenchange', pFn);
    }
}
