import { Config } from './Config.js';

export class Console {
    constructor(pDomElement) {
        this.target = pDomElement;
        if (!Config.DEBUG) {
            this.hide();
            return;
        };
        this.addMessage("~Debug Console~");
    }

    trace(args) {
        if (!Config.DEBUG) return;
        let result = "",
            i;

        for (i = 0; i < args.length; i++) {
            result += (args[i]) + " ";
        }
        this.target.innerHTML += result.toString() + " <br />";
        console.log(result.toString());
    }

    addMessage() {
        if (!Config.DEBUG) return;
        let result = "",
            i;

        for (i = 0; i < arguments.length; i++) {
            result += (arguments[i]) + " ";
        }
        this.target.innerHTML += result.toString() + " <br />";
        console.log(result.toString());
    }

    message() {
        if (!Config.DEBUG) return;
        let result = "",
            i;

        for (i = 0; i < arguments.length; i++) {
            result += (arguments[i]) + " ";
        }
        this.target.innerHTML = result.toString();
        console.log(result.toString());
    }

    clear() {
        if (!Config.DEBUG) return;
        this.target.innerHTML = "";
    }

    show() {
        this.target.style.display = "block";
    }

    hide() {
        this.target.style.display = "none";
    }

}